(window.MATRIX_DATA_PARTS ||= Object.create(null))["data/poems-0037.js"] = [{"id":"poem-f129638caf28d3970ec0edbd","title":"照镜","author":"李益","dynasty":"唐","verses":["衰鬓朝临镜，将看却自疑。","慙君明似月，照我白如丝。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.15000.json#record-66322ac8-46e8-4561-9858-ece254a0de59","tags":[]},{"id":"poem-f1307fb536ad77187a8ba987","title":"鹭鸶","author":"无则","dynasty":"唐","verses":["白苹红蓼碧江涯，日暖双双立睡时。","愿揭金笼放归去，却随沙鹤鬬轻丝。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.45000.json#record-085b5c16-f6f9-4495-8b0c-c404dda4d477","tags":[]},{"id":"poem-f1311faccb1e8b97d05b53a2","title":"石州词・石州慢·歌阕阳关","author":"胡松年","dynasty":"宋","verses":["歌阕阳关，肠断短亭，惟有离别。","画船送我薰风，瘦马迎人飞雪。","平生幽梦，岂知塞北江南，而今真叹河山阔。","屈指数分携，早许多时节。","愁绝。","雁行点点云垂，木叶霏霏霜滑。","正是荒城落日，空山残月。","一尊谁念我，苦憔悴天涯，陡觉生华发。","赖有紫枢人，共扬鞭丹阙。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.6000.json#record-826","tags":[]},{"id":"poem-f131cbaeaf3dd0d514d43acb","title":"卜算后","author":"高明《蔡伯喈琵琶记》","dynasty":"元","verses":["梦里分明有鬼神，想是天怜念。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-5144","tags":[]},{"id":"poem-f1321950f52830ea55b2d1e9","title":"送友人之永嘉","author":"项斯","dynasty":"唐","verses":["长贫知不易，去计拟何逃。","相对人愁别，经过几处劳。","城连沙岫远，山断夏云高。","犹想成诗处，秋灯半照涛。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.30000.json#record-12396b57-e35d-4e9f-bff4-5e36bf5579af","tags":[]},{"id":"poem-f1347cd81a4fad8dd00dc255","title":"江南曲","author":"李益","dynasty":"唐","verses":["长乐花枝雨点销，江城日暮好相邀。","春楼不闭葳蕤锁，绿水回连宛转桥。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.15000.json#record-3b28eace-a2e8-4627-a7ef-02e3b901be8f","tags":[]},{"id":"poem-f135e2963644d42ad440fa1c","title":"天池圣灯  其二","author":"萧之敏","dynasty":"宋","verses":["细如珠颗大如杯，照夜浮空去复来。","神物戏人安可料，密移星斗下岩隈。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.120000.json#record-9822a40a-2f3b-4ac3-955d-0e7f5833da2b","tags":[]},{"id":"poem-f13c88d5867116d672041b00","title":"拟古·美人临残月","author":"纳兰性德","dynasty":"清","verses":["美人临残月，无言若有思。","含颦但斜睇，吁嗟怜者谁。","予本多情人，寸心聊自持。","浩歌幽兰曲，援琴终不怡。","私恨托远梦，初日照帘帏。"],"enabled":true,"collection":"纳兰词","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/纳兰性德/纳兰性德诗集.json#record-249","tags":[]},{"id":"poem-f13ddace4c9aba2c5cbc6ca5","title":"前腔","author":"施惠《幽闺记》","dynasty":"元","verses":["(小生)紧降阶，释缚扶将起，是兄弟负恩忘义。","这是何人？(生)是我浑家。","(小生)尊嫂受礼。","谁知此地能完聚？(旦)愁为喜，深谢得贤叔盗跖。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-2965","tags":[]},{"id":"poem-f13efe0464c6816ec3623a3b","title":"扶南曲歌词五首 一","author":"王维","dynasty":"唐","verses":["翠羽流苏帐，春眠曙不开。","羞从面色起，娇逐语声来。","早向昭阳殿，君王中使催。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.5000.json#record-fd3944f6-676d-4c8b-90ca-d694a69f30d9","tags":[]},{"id":"poem-f14099a42c00759604afd982","title":"酬岑二十主簿秋夜见赠之作","author":"高适","dynasty":"唐","verses":["舍下蛩乱鸣，居然自萧索。","缅怀高秋兴，忽枉清夜作。","感物我心劳，凉风惊二毛。","池枯菡萏死，月出梧桐高。","如何异乡县，复得交才彦。","汨没嗟后时，蹉跎耻相见。","箕山别来久，魏阙谁不恋。","独有江海心，悠悠未尝倦。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.10000.json#record-cf44f6f5-acdc-449d-b10e-3096bfde8eed","tags":[]},{"id":"poem-f142da5ea09c759d24ee7055","title":"南池杂咏五首 虚舟","author":"皎然","dynasty":"唐","verses":["虚舟动又静，忽似去逢时。","触物知无迕，为梁幸见遗。","因风到此岸，非有济川期。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.45000.json#record-3099b9b0-2454-4e75-8d51-947f01a3485f","tags":[]},{"id":"poem-f14b0be4c5b715f09c205a1c","title":"前腔","author":"高明《蔡伯喈琵琶记》","dynasty":"元","verses":["公公这病呵，百愁万苦千生受，妆成这症候。","便做这药吃时呵，纵然救得目前，怎免得忧与愁？料应不会久。","他只为不见孩儿么？这病可时，除非是子孝父心宽，方才可救。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-5101","tags":[]},{"id":"poem-f1579247aed5c46e47f8cd44","title":"江亭赠别","author":"马戴","dynasty":"唐","verses":["长亭晚送君，秋色渡江𣸣。","衰柳风难定，寒涛雪不分。","猨声离楚峡，帆影入湘云。","独泛扁舟夜，山钟可卧闻。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.30000.json#record-279e6dda-6843-424b-a68e-1ad2e59a7797","tags":[]},{"id":"poem-f157c810826f9e21f9d9ab63","title":"凉州词二首 一","author":"王翰","dynasty":"唐","verses":["葡萄美酒夜光杯，欲饮琵琶马上催。","醉卧沙场君莫笑，古来征战几人回。"],"enabled":true,"collection":"唐诗三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/唐诗三百首.json#record-0445f296-5816-4ab9-a617-7d8ed29088ea","tags":["唐诗三百首","豪放","战争","边塞","宴饮","七言绝句"]},{"id":"poem-f15a65039a7ab761399ea8c3","title":"和黄仲秉喜雨","author":"张栻","dynasty":"宋","verses":["雨后清泉遶舍流，悬知耘耜遍南州。","占相岁事端无恙，劳苦农人亦少休。","好句收功经百炼，弥旬不见便三秋。","闲来只愿长丰稔，江海白鸥盟共求。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.150000.json#record-5e4ab7eb-325c-4453-bef6-f07414cc1a2a","tags":[]},{"id":"poem-f15a71a4989ab1a74566d772","title":"小游仙诗九十八首 七十三","author":"曹唐","dynasty":"唐","verses":["紫水风吹劒树寒，水边年少下红鸾。","未知百一穷阳数，略请先生止的看。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.35000.json#record-d2d41c2a-1a38-40dc-b50d-9f19964c1751","tags":[]},{"id":"poem-f1601b480f5f1520aecfd21d","title":"小古镜","author":"项斯","dynasty":"唐","verses":["字已无人识，唯应记铸年。","见来深似水，携去重于钱。","鸾翅巢空月，菱花徧小天。","宫中照黄帝，曾得化为仙。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.30000.json#record-56cb0805-f673-4961-a7ed-e2ca4dedefc8","tags":[]},{"id":"poem-f16228bb78c8634aa37adb57","title":"郭郎儿近拍·帝里","author":"柳永","dynasty":"宋","verses":["帝里。","闲居小曲深坊，庭院沈沈朱户闭。","新霁。","畏景天气。","薰风帘幕无人，永昼厌厌如度岁。","愁悴。","枕簟微凉，睡久辗转慵起。","砚席尘生，新诗小阕，等闲都尽废。","这些儿、寂寞情怀，何事新来常恁地。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.0.json#record-221","tags":[]},{"id":"poem-f162dc2609e46ee665bdc041","title":"观雪","author":"米芾","dynasty":"宋","verses":["月姊封银界，龙君幻玉壶。","江南三尺雪，人道十年无。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.60000.json#record-4d5956ed-09fd-4fc7-b20d-dbdf0b0b4b1d","tags":[]},{"id":"poem-f1704d265e02612151f2ec0b","title":"千秋岁·数声𫛸鴂","author":"张先","dynasty":"宋","verses":["数声𫛸鴂。","又报芳菲歇。","惜春更把残红折。","雨轻风色暴，梅子青时节。","永丰柳，无人尽日飞花雪。","莫把幺弦拨。","怨极弦能说。","天不老，情难绝。","心似双丝网，中有千千结。","夜过也，东窗未白凝残月。"],"enabled":true,"collection":"宋词三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/宋词三百首.json#record-157","tags":["宋词三百首"]},{"id":"poem-f1819a14a90aa884703e6cfc","title":"前腔","author":"刘唐卿《白兔记》","dynasty":"元","verses":["(生)上告妻妻听，怕你执不定。","你哥嫂忒毒狠，只恐你口说无凭准。","我独自守孤另，恐耽阁两下成病。","(合前)。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-8882","tags":[]},{"id":"poem-f186ee6d9d1becd81cabbd12","title":"齐天乐·烟波桃叶西陵路","author":"吴文英","dynasty":"宋","verses":["烟波桃叶西陵路，十年断魂潮尾。","古柳重攀，轻鸥聚别，陈迹危亭独倚。","凉飔乍起。","渺烟碛飞帆，暮山横翠。","但有江花，共临秋镜照憔悴。","华堂烛暗送客，眼波回盼处，芳艳流水。","素骨凝冰，柔葱蘸雪，犹忆分瓜深意。","清尊未洗。","梦不湿行云，漫沾残泪。","可惜秋宵，乱蛩疏雨里。"],"enabled":true,"collection":"宋词三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/宋词三百首.json#record-6","tags":["宋词三百首"]},{"id":"poem-f194aa12a400dbff66de5082","title":"锦堂春·帘际一痕轻绿","author":"纳兰性德","dynasty":"清","verses":["帘际一痕轻绿，墙阴几簇低花。","夜来微雨西风软，无力任欹斜。","仿佛个人睡起，晕红不著铅华。","天寒翠袖添凄楚，愁近欲栖鸦。"],"enabled":true,"collection":"纳兰词","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/纳兰性德/纳兰性德诗集.json#record-75","tags":[]},{"id":"poem-f19dccbb8b94a2dd1cd3ffdf","title":"偈颂 一","author":"文偃","dynasty":"唐","verses":["云门耸剔（《天圣广灯录》卷二十作「踢」、《五灯会元》卷十五作「峻」）白云低，水急游鱼不敢栖。","入户已知来见解，何劳更（《天圣广灯录》、《五灯会元》作「再」）举轹中泥。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.55000.json#record-d053634c-f6c2-4e94-8f5b-30526a12cc4a","tags":[]},{"id":"poem-f1a0229fdd54864c8ace73ea","title":"首春","author":"太宗皇帝","dynasty":"唐","verses":["寒随穷律变，春逐鸟声开。","初风飘带柳，晚雪间花梅。","碧林青旧竹，绿沼翠新苔。","芝田初雁去，绮树巧鸎来。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.0.json#record-75f1983d-2147-4028-a0d8-fdfc4c2d8244","tags":[]},{"id":"poem-f1aa87b12308a4c80afd692d","title":"偈颂十二首  其九","author":"释原妙","dynasty":"宋","verses":["封却拄杖头，结却布袋口。","禁在铁围山，枷上重增杻。","有中拷出无，无中拷出有。","痛楚百千般，不离者窠臼。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.240000.json#record-cb0a45b9-c765-422f-92b5-37a2279512aa","tags":[]},{"id":"poem-f1b5141515e3a6bc7d112565","title":"北征","author":"杜甫","dynasty":"唐","verses":["皇帝二载秋，闰八月初吉。","杜子将北征，苍茫问家室。","维时遭艰虞，朝野少暇日。","顾慙恩私被，诏许归蓬荜。","拜辞诣阙下，怵惕久未出。","虽乏谏诤姿，恐君有遗失。","君诚中兴主，经纬固密勿。","东胡反未已，臣甫愤所切。","挥涕恋行在，道途犹恍惚。","乾坤含疮痍，忧虞何时毕。","靡靡逾阡陌，人烟眇萧瑟。","所遇多被伤，呻吟更流血。","回首凤翔县，旌旗晚明灭。","前登寒山重，屡得饮马窟。","邠郊入地底，泾水中荡潏。","猛虎立我前，苍崖吼时裂。","菊垂今秋花，石戴古车辙。","青云动高兴，幽事亦可悦。","山果多琐细，罗生杂橡栗。","或红如丹砂，或黑如点漆。","雨露之所濡，甘苦齐结实。","缅思桃源内，益叹身世拙。","坡陀望鄜畤，岩谷互出没。","我行已水滨，我仆犹木末。","鸱鸟鸣黄桑，野鼠拱乱穴。","夜深经战场，寒月照白骨。","潼关百万师，往者散何卒。","遂令半秦民，残害为异物。","况我堕胡尘，及归尽华发。","经年至茅屋，妻子衣百结。","恸哭松声回，悲泉共幽咽。","平生所娇儿，颜色白胜雪。","见耶背面啼，垢腻脚不韤。","床前两小女，补绽才过膝。","海图坼波涛，旧绣移曲折。","天吴及紫凤，颠倒在裋褐。","老夫情怀恶，呕泄卧数日。","那无囊中帛，救汝寒凛栗。","粉黛亦解苞，衾裯稍罗列。","瘦妻面复光，痴女头自栉。","学母无不为，晓妆随手抹。","移时施朱铅，狼藉画眉阔。","生还对童穉，似欲忘饥渴。","问事竞挽须，谁能即嗔喝。","飜思在贼愁，甘受杂乱聒。","新归且慰意，生理焉能说。","至尊尚蒙尘，几日休练卒。","仰观天色改，坐觉祅气豁。","阴风西北来，惨澹随回鹘。","其王愿助顺，其俗善驰突。","送兵五千人，驱马一万匹。","此辈少为贵，四方服勇决。","所用皆鹰腾，破敌过箭疾。","圣心颇虚伫，时议气欲夺。","伊洛指掌收，西京不足拔。","官军请深入，蓄锐何俱发。","此举开青徐，旋瞻略恒碣。","昊天积霜露，正气有肃杀。","祸转亡胡岁，势成擒胡月。","胡命其能久，皇纲未宜绝。","忆昨狼狈初，事与古先别。","奸臣竟葅醢，同恶随荡析。","不闻夏殷衰，中自诛褒妲。","周汉获再兴，宣光果明哲。","桓桓陈将军，仗钺奋忠烈。","微尔人尽非，于今国犹活。","凄凉大同殿，寂寞白兽闼。","都人望翠华，佳气向金阙。","园陵固有神，埽洒数不缺。","煌煌太宗业，树立甚宏达。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.10000.json#record-a335f6c4-e9df-47d5-879d-9ebd3c1baf5c","tags":["叙事","战争","长诗","爱国","忧国忧民"]},{"id":"poem-f1ba681b8f557f3cc2e2c78e","title":"行都饯岁","author":"孙嵩","dynasty":"宋","verses":["插架余残历，挑灯忆故乡。","年光蛇赴壑，羁旅雁随阳。","禁阙迎傩鼓，邻街祭灶香。","英雄须自力，容易鬓毛苍。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.240000.json#record-a0935761-3d71-41b5-a057-4029c6224c9a","tags":[]},{"id":"poem-f1be11547403d2b959404b75","title":"浣溪沙·珠履三千巧斗妍","author":"史浩","dynasty":"宋","verses":["珠履三千巧斗妍。","就中弓窄只迁迁。","恼伊刬袜转堪怜。","舞罢有香留绣褥，步馀无迹在金莲。","好随云雨楚峰前。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.8000.json#record-156","tags":[]},{"id":"poem-f1c39eecc483758e8a05a67e","title":"彭蠡湖春望","author":"项斯","dynasty":"唐","verses":["湖亭东极望，远棹不须回。","遍草新湖落，连天众鴈来。","芦洲残照尽，云障积烟开。","更想鸱夷子，扁舟安在哉。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.30000.json#record-bf25dbb3-393f-4e20-b695-2b84739ebcc6","tags":[]},{"id":"poem-f1c7f4c317ed31c7564d95eb","title":"宿建德江","author":"孟浩然","dynasty":"唐","verses":["移舟泊烟渚，日暮客愁新。","野旷天低树，江清月近人。"],"enabled":true,"collection":"唐诗三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/唐诗三百首.json#record-0bed9b02-991e-4e28-b631-86640147a712","tags":["唐诗三百首","描写水","写景","思乡","水","月亮","五言绝句","写水"]},{"id":"poem-f1e1e231ac450a4bb463f81e","title":"早发","author":"杜甫","dynasty":"唐","verses":["有求常百虑，斯文亦吾病。","以兹朋故多，穷老驱驰幷。","早行篙师怠，席挂风不正。","昔人戒垂堂，今则奚奔命。","涛飜黑蛟跃，日山黄雾映。","烦促瘴岂侵，颓倚睡未醒。","仆夫问盥栉，暮颜腼青镜。","随意簪葛巾，仰慙林花盛。","侧闻夜来寇，幸喜囊中净。","艰危作远客，干请伤直性。","薇蕨饿首阳，粟马资历聘。","贱子欲适从，疑误此二柄。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.10000.json#record-1100cc25-0c98-41cd-ba29-9d042906fbc7","tags":[]},{"id":"poem-f1e1eb6d3e1150c46ac06f4c","title":"浣溪沙·绿叶红花媚晓烟","author":"晏殊","dynasty":"宋","verses":["绿叶红花媚晓烟。","黄蜂金蕊欲披莲。","水风深处懒回船。","可惜异香珠箔外，不辞清唱玉尊前。","使星归觐九重天。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.0.json#record-440","tags":[]},{"id":"poem-f1f236b0a5801aa123884e75","title":"春晚东园晓思","author":"薛逢","dynasty":"唐","verses":["劒外春余日更长，东园留醉乐高张。","松杉露滴无情泪，桃杏风飘不语香。","莺恋叶深啼绿树，燕窥巢稳坐雕梁。","也知留滞年华晚，争那罇前乐未央。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.30000.json#record-5dc7a7a3-27ed-4b56-b96d-1167b1279057","tags":[]},{"id":"poem-f1f2d992acad7c0cbb8d4fa4","title":"山北东林诗","author":"修睦","dynasty":"唐","verses":["二林乘兴往，几日见归程。","有翼便归程。","有翼便飞去，何劳更此生。","川长云迤逦，溪静月分明。","果熟僧相待，庭闲鹤自行。","搘颐柽栉稳，远梦石床平。","是院水皆到，无窗书不盈。","登楼双眼饱，倚桧片心清。","夜永莲花漏，殿高神运名。","参空寒峤色，压雨古松声。","早晚携瓶入，孤吟猨鸟情。","（见《永乐大典》卷八七八二引《九江府志》。","二诗皆据《古籍整理出版情况简报》一五六期张忱石先生《〈永乐大典〉续印本印象记》转录。","）。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.55000.json#record-f01a5a59-9427-43e2-a41c-83b6dbbbacdf","tags":[]},{"id":"poem-f1f75edfc491807c2f2bf003","title":"庐山得元侍御书","author":"李涉","dynasty":"唐","verses":["慙君知我命龙钟，一纸书来意万重。","正著白衣寻古寺，忽然邮递到云峰。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.25000.json#record-dbf696ea-8ec6-4def-b6d5-fa141c7324f9","tags":["庐山"]},{"id":"poem-f1f7ffea0267be460bb6590d","title":"览春牓喜孙鄠成名","author":"曹松","dynasty":"唐","verses":["门外报春牓，喜君天子知。","旧愁浑似雪，见日总消时。","塔下牡丹气，江头杨柳丝。","风光若有分，无处不相宜。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.40000.json#record-3e188e47-e2bf-484a-b003-b09270b4e6ff","tags":[]},{"id":"poem-f1f818cb542f0c847020d767","title":"求仙行","author":"张籍","dynasty":"唐","verses":["汉皇欲作飞仙子，年年采药东海里。","蓬莱无路海无边，方士舟中相枕死。","招摇在天回白日，甘泉玉树无仙实。","九皇真人终不下，空向离宫祠太乙。","丹田有气凝素华，君能保之升绛霞。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.20000.json#record-49522bf6-df30-4a45-a34f-68ed4c97bcc9","tags":[]},{"id":"poem-f1f8e6054c078a6cc83a48a6","title":"破山璎珞桧","author":"释居简","dynasty":"宋","verses":["雪枝新纵纵，霜子旧玲玲。","漙露烦添缀，萦风缓剪零。","贯珠烦蚁度，编贝倩谁经。","瑶草随山尽，来寻千岁苓。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.180000.json#record-18d91836-3af1-4dda-91a3-cc45e8ef368e","tags":[]},{"id":"poem-f1fc91f4684bdaea76556f09","title":"赠胡天师","author":"则天皇后","dynasty":"唐","verses":["高人叶高志，山服往山家。","迢迢间风月，去去隔烟霞。","碧岫窥玄洞，玉灶炼丹砂。","今日星津上，延首望灵槎。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.0.json#record-ebc91c19-1486-4a61-84fb-649eadef3f51","tags":[]},{"id":"poem-f21324f8b53ed32bbde8d9e1","title":"郊庙歌辞 享太庙乐章 大政舞","author":"张说","dynasty":"唐","verses":["于赫元命，权舆帝文。","天齐八柱，地半三分。","宗庙观德，笙镛乐勋。","封唐之兆，成天下君。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.0.json#record-884a1a63-e25d-4735-8987-3e557d13bb58","tags":[]},{"id":"poem-f21aed10d71b3bc12349d25f","title":"诉衷情·金风轻透碧窗纱","author":"魏承班","dynasty":"五代","verses":["金风轻透碧窗纱，银釭焰影斜。","倚枕卧，恨何赊，山掩小屏霞。","云雨别吴娃，想容华。","梦成几度绕天涯，到君家。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-9-juan.json#record-7","tags":[]},{"id":"poem-f21b9391e3160b8a336f8b3b","title":"同袁高使君送李判官使回","author":"皎然","dynasty":"唐","verses":["庾公欢此别，路远意犹赊。","为出塘边柳，荣归府中花。","驰阳照古堞，遥思凝寒笳。","延步下前渚，溯觞流浅沙。","湖光引行色，轻舸傍残霞。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.45000.json#record-f3facf68-cd48-43d3-8e23-db28e701b9bd","tags":[]},{"id":"poem-f2229eff18903fda8fe6f549","title":"游喷玉潭  其二","author":"司马光","dynasty":"宋","verses":["万木吼穹谷，驽骀屹不前。","犹胜望尘客，伫立九衢边。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.30000.json#record-2d1a4c25-52c2-48b3-a461-dafe2d55b708","tags":[]},{"id":"poem-f225ee6fd5b68575033d37d8","title":"春秋战国门 郑相","author":"周昙","dynasty":"唐","verses":["郑相清贤慎有余，好鱼鱼至竟何如。","退鱼留得终身禄，禄在何忧不得鱼。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.40000.json#record-53c3cdf4-6fdd-4f53-9db7-a02d71629b78","tags":[]},{"id":"poem-f230b3c5e0ed940047f2fa7c","title":"忆多娇","author":"柯丹邱《荆钗记》","dynasty":"元","verses":["(末)愁哽咽，情惨切，萱堂苦逼中道绝，暮忆朝思难诉说。","(合)丧溺江心，丧溺江心，永远传扬孝烈。","(老旦)我那媳妇的儿，我有半年粮食，也不见得到你家来。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-8238","tags":[]},{"id":"poem-f231894d79662bc0792feaa2","title":"满庭芳·一阵轻香","author":"葛立方","dynasty":"宋","verses":["一阵轻香，不知来处，元来梅已舒英。","出篱含笑，芳意为人倾。","细看高标孤韵，谁家有、别得花人。","应须是，魏征妩媚，夷甫太鲜明。","北枝，方半吐，水边疏影，绰约娉婷。","问横空皎月，匝地寒霙。","何似此花清绝，凭君为、子细推评。","幽奇处，素娥青女，著意为横陈。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.8000.json#record-512","tags":[]},{"id":"poem-f239d1f1aa1a40b426c0bfbc","title":"菩萨蛮·江城烽火连三月","author":"李弥逊","dynasty":"宋","verses":["江城烽火连三月。","不堪对酒长亭别。","休作断肠声。","老来无泪倾。","风高帆影疾。","目送舟痕碧。","锦字几时来。","薰风无雁回。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.6000.json#record-56","tags":[]},{"id":"poem-f23bc13180b130b9c571da48","title":"句","author":"大闲","dynasty":"唐","verses":["霜沾草迳寒风急，鴈度秋林落叶频。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.50000.json#record-b3faeb87-ce88-4455-b9ab-c308d4634084","tags":[]},{"id":"poem-f23f0241331c405ab73463dc","title":"江头送别","author":"徐田臣《杀狗记》","dynasty":"元","verses":["杀一狗，杀一狗，生魂那里？思量起，思量起，泪珠暗垂。","当初养你防家计，谁知道今日有灾危！(杀介。","旦、贴上)。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-1885","tags":[]},{"id":"poem-f24384143e1c0b3afe4b5e7a","title":"蒙恩除荆湖广南宣抚兼知潭州具奏辞免  其二","author":"李纲","dynasty":"宋","verses":["昔年宣抚两河间，行次覃怀已召还。","壮志久拚身似叶，巧言终使罪如山。","士风欺蔽犹前日，君命牢辞秪厚颜。","回首追思七年事，孤危易感涕空澘。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.90000.json#record-18915ff8-f6f6-4527-8791-4da162c583c0","tags":[]},{"id":"poem-f25736c32c100ed8d27c8624","title":"柳枝词","author":"李涉","dynasty":"唐","verses":["锦池江上柳垂桥，风引蝉声送寂寥。","不必如丝千万缕，只禁离恨两三条。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.25000.json#record-9b8f9ff5-ec06-4f60-9980-b116842374ec","tags":[]},{"id":"poem-f257b8aca94eaae30136f840","title":"喜雪六首  其四","author":"陈造","dynasty":"宋","verses":["淮春之楼高突兀，凭栏小耐寒如割。","平湖穹山两西子，爱此鲜粧巧涂抹。","回首斜阳照屋梁，玉际坤舆尚摧压。","今宵更呼甓社龙，高挂明珠照空阔。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.150000.json#record-a8b3521f-3f0a-40c4-9b6b-5eba4e1a2940","tags":[]},{"id":"poem-f260265047c7596831a4c6f2","title":"仙源即事三首  其二","author":"王镃","dynasty":"宋","verses":["开试丹头采异方，归来洗药井中香。","松花酒后黄精饭，卧看青山到夕阳。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.240000.json#record-77b43814-e3b0-433b-b7c6-4c90528b4b46","tags":[]},{"id":"poem-f2760bfc3a562534e0606b97","title":"菩萨蛮·黄云紫塞三千里","author":"纳兰性德","dynasty":"清","verses":["黄云紫塞三千里，女墙西畔啼乌起。","落日万山寒，萧萧猎马还。","笳声听不得，入夜空城黑。","秋梦不归家，残灯落碎花。"],"enabled":true,"collection":"纳兰词","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/纳兰性德/纳兰性德诗集.json#record-207","tags":[]},{"id":"poem-f2767d8bfe35edc98d05d383","title":"下山虎","author":"徐田臣《杀狗记》","dynasty":"元","verses":["有一个醉汉倒在街坊，大雪纷纷下，看着惨伤。","我好意教你开门早商量，笼些火焰，教他吃口滚汤。","救人一命活，胜造七级浮屠福寿昌。","你若不开门，后倘或死亡，带累邻家遭祸殃。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-1764","tags":[]},{"id":"poem-f278b3d835bf7c6fce83b71e","title":"江行无题一百首 三十一","author":"钱珝","dynasty":"唐","verses":["岸草连荒色，村声乐稔年。","晚晴贪获稻，闲却采菱船。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.40000.json#record-c875f5b6-3f93-4d07-92f5-70078123cedb","tags":[]},{"id":"poem-f27dc64af931e341803a7156","title":"偈颂（幷序○序为南岳齐己撰） 八十四","author":"居遁","dynasty":"唐","verses":["祇为因无用，方能伴住山。","不因无用后，伴我住应难。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.55000.json#record-c58149cd-4d62-41d4-9302-b9c397c28949","tags":["衡山"]},{"id":"poem-f2809373cdae4eaff2cc5fc7","title":"郊庙歌辞 释奠武成王乐章 迎俎酌献","author":"于邵","dynasty":"唐","verses":["五齐洁，九牢硕。","梡橛循，罍斝涤。","进具物，扬鸿绩。","和奏发，高灵寂。","虔告终，繁祉锡。","昭秩祀，永无易。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.0.json#record-b9d3edd9-a17c-47ce-b299-241f611917cd","tags":[]},{"id":"poem-f283a4871c4ad30b186f9595","title":"定叟弟频寄黄蘗仰山新芽尝口占小诗适灾患亡聊久不得遣寄今日方能写此  其二","author":"张栻","dynasty":"宋","verses":["集云峰顶风霜饱，黄蘗洲前水石清。","不入贡包供玉食，祇应山泽擅高名。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.150000.json#record-cbb15112-09bb-440c-ac86-28f2f8969bbd","tags":[]},{"id":"poem-f28862cf1995af796f37d316","title":"南浦·风悲画角","author":"孔夷","dynasty":"宋","verses":["风悲画角，听单于、三弄落谯门。","投宿骎骎征骑，飞雪满孤村。","酒市渐闲灯火，正敲窗、乱叶舞纷纷。","送数声惊雁，下离烟水，嘹唳度寒云。","好在半胧溪月，到如今、无处不销魂。","故国梅花归梦，愁损绿罗裙。","为问暗香闲艳，也相思、万点付啼痕。","算翠屏应是，两眉馀恨倚黄昏。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.4000.json#record-578","tags":["宋词三百首"]},{"id":"poem-f28dc6dfd0d3a6e2a13dcede","title":"望江南・忆江南·江南水","author":"王琪","dynasty":"宋","verses":["江南水，江路转平沙。","雨霁高烟收素练，风晴细浪吐寒花。","迢递送星槎。","名利客，飘泊未还家。","西塞山前渔唱远，洞庭波上雁行斜。","征棹宿天涯。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.0.json#record-848","tags":["洞庭湖"]},{"id":"poem-f2903ce255a507d00fdcab3d","title":"送修武郑主簿纠郡梓潼兼寄王舍人八韵","author":"徐铉","dynasty":"宋","verses":["杖策辞清浴，驱车向梓潼。","栖鸾才乍展，叱驭气方雄。","暂割趋庭恋，将伸纠郡功。","诗清冲密雪，别酒愬寒风。","山水秦关外，烟花锦里东。","府公名素重，语掾道仍同。","坐啸新知洽，随行旧分通。","当令从此去，不复数文翁。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.0.json#record-0fc5a2c7-2f47-4fe7-a559-d048df8f7530","tags":[]},{"id":"poem-f29533b199846235f8175937","title":"再次沈韵","author":"曾协","dynasty":"宋","verses":["独将春信报天涯，岂是无情定有知。","巧占岁寒怜韵胜，冥搜诗句愧辞枝。","松篁有约成三友，桃李争功彼一时。","珍重休文三昧手，尽回佳处入清诗。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.120000.json#record-c6056cb0-1969-4b59-b663-0784aa26dca9","tags":[]},{"id":"poem-f29e0d9d2ff72c263fc42355","title":"宿巾子山禅寺","author":"任翻","dynasty":"唐","verses":["绝顶新秋生夜凉，鹤翻松露滴衣裳。","前峰月映半江水，僧在翠微开竹房。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.40000.json#record-25748fc8-5511-4aa3-b7b2-ee7c7b8af56d","tags":[]},{"id":"poem-f2a7fe68e1721d8baa788b29","title":"忆秦娥·湖光碧","author":"蔡伸","dynasty":"宋","verses":["湖光碧。","春花秋月无今昔。","无今昔。","十年往事，尽成陈迹。","玉箫声断云屏隔。","山遥水远长相忆。","长相忆。","一生怀抱，为君牵役。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.6000.json#record-987","tags":[]},{"id":"poem-f2b56e42e2bdeaeb152b9e7e","title":"送智玄首座归蜀中旧山","author":"刘得仁","dynasty":"唐","verses":["像教得重兴，因师说大乘。","从来悟明主，今去证高僧。","蜀国烟霞异，灵山水月澄。","乡闾诸善友，喜似见南能。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.30000.json#record-aa4780fe-f910-470e-bdad-95daf6277090","tags":[]},{"id":"poem-f2bac11e7c6882a4c43c9aec","title":"生查子","author":"刘唐卿《白兔记》","dynasty":"元","verses":["(生上)满腹愁如织，此恨何日白？难道男儿不泪垂？事到如流水。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-8859","tags":[]},{"id":"poem-f2d0e3945e3cc59b6b3bfa9b","title":"夜行黄花川","author":"胡皓","dynasty":"唐","verses":["的的（旳旳）夜绵绵，斜斗历高天。","露浩空山月，风秋洞壑泉。","饥鼯啼远树，暗鸟宿长川。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.50000.json#record-2b2ca32e-7c6d-45e6-8e2d-708a615f5a61","tags":[]},{"id":"poem-f2dcd0044b8dbea70b49c233","title":"小苑春望宫池柳色","author":"杨凌","dynasty":"唐","verses":["上苑闲游早，东风柳色轻。","储胥遥掩映，池水隔微明。","春至条偏弱，寒余叶未成。","和烟变浓淡，转日异阴晴。","不独芳菲好，还因雨露荣。","行人望攀折，远翠暮愁生。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.15000.json#record-59df755e-5961-4146-80e9-e15c9cedea8a","tags":[]},{"id":"poem-f2f2c299bad99d80f957edc1","title":"赠余干袁明府","author":"曹松","dynasty":"唐","verses":["一雨西城色，陶家心自清。","山衔中郭分，云卷下湖程。","公署闻流木，人烟入废城。","难忘楚尽处，新有越吟生。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.40000.json#record-d0eb8238-13ab-4dce-9ade-9fdc54d7da4e","tags":[]},{"id":"poem-f2f790a102ca0a6b778ce1ca","title":"咏史诗 细腰宫","author":"胡曾","dynasty":"唐","verses":["楚王辛苦战无功，国破城荒霸业空。","唯有青春花上露，至今犹泣细腰宫。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.35000.json#record-d6127d65-19b9-491b-9107-11a56b13b928","tags":[]},{"id":"poem-f2f8450665ee3c92ded0bbb5","title":"读渊明传","author":"高吉","dynasty":"宋","verses":["谁为栖栖鲁孔丘，辙环天下果何求。","爱人学道行吾志，束带何伤见督邮。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.210000.json#record-dec833e8-e10d-4656-bf40-a7c7cb2d7095","tags":[]},{"id":"poem-f2fb29b1bd8ccbd9ef443e10","title":"惠山寺","author":"刘跂","dynasty":"宋","verses":["从来未到山头寺，应在武陵深处藏。","汉水文人生自拙，香山居士兴何长。","四旁岛屿娟娟绿，万顷菰蒲靡靡香。","且醉尊中眼前物，瀛洲蓬岛两微茫。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.60000.json#record-65c88cf7-ad70-4d08-a46c-94847a743b30","tags":[]},{"id":"poem-f301bbb57daf0c238fafcd85","title":"浣溪沙·暖日温风破浅寒","author":"吕本中","dynasty":"宋","verses":["暖日温风破浅寒。","短青无数簇幽栏。","三年春在病中看。","中酒心情浑似梦，探花时候不曾闲。","几年芳信隔秦关。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.6000.json#record-735","tags":[]},{"id":"poem-f3042aa0fc182756324a4ea8","title":"瞻彼洛矣","author":"佚名","dynasty":"先秦","verses":["瞻彼洛矣，维水泱泱。君子至止，福禄如茨。韎韐有奭，以作六师。","瞻彼洛矣，维水泱泱。君子至止，鞸琫有珌。君子万年，保其家室。","瞻彼洛矣，维水泱泱。君子至止，福禄既同。君子万年，保其家邦。"],"enabled":true,"collection":"诗经","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/诗经/shijing.json#record-212","tags":[]},{"id":"poem-f3096828fdb8167acc2e9d13","title":"崔驸马养鹤","author":"张籍","dynasty":"唐","verses":["身闲无事称高情，已有人间章句名。","求得鹤来教翦翅，望仙台下亦将行。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.20000.json#record-d60258ad-0f56-472e-b6f1-eae37b98766d","tags":[]},{"id":"poem-f31626ab4f306b6352ce250e","title":"春寻花柳得情（三八一二）","author":"宋家娘子","dynasty":"唐","verses":["美人林里趁鵶儿，银甲花间不觉遗。","连忙借问娇鹦鹉，鸟鸟衔将与阿谁？。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.50000.json#record-ddca4880-a42d-4a45-b3de-56508296f058","tags":[]},{"id":"poem-f3196a995a4c395ea6f12eb0","title":"至德中途中书事却寄李僴","author":"卢纶","dynasty":"唐","verses":["乱离无处不伤情，况复看碑对古城。","路遶寒山人独去，月临秋水鴈空惊。","颜衰重喜归乡国，身贱多惭问姓名。","今日主人还共醉，应怜世故一儒生。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.15000.json#record-6846805b-01f3-442f-b7be-220466bd9c57","tags":[]},{"id":"poem-f32117be543cbfcb0b44d93c","title":"同前","author":"无名氏《张协状元》","dynasty":"元","verses":["自古道东床，女婿有万千。","怎知它一举，便做着状元。","奴只道，永团圆。","必来接，那丝鞭。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-2624","tags":[]},{"id":"poem-f326fedeba28a28b3154c6e8","title":"晦日陪颜使君白苹洲集","author":"皎然","dynasty":"唐","verses":["南朝分古郡，山水似湘东。","堤月吴风在，湔裾楚客同。","桂寒初结斾，苹小欲成丛。","时晦佳游促，高歌听未终。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.45000.json#record-d1b53657-010b-4711-969f-c489cace7eb5","tags":[]},{"id":"poem-f332abe4638c4997c491b563","title":"宫词  其六七","author":"张公庠","dynasty":"宋","verses":["佳人唯是惜韶年，嬾向红窗理管弦。","锦席安排胡蝶局，深宫不忌赌金钱。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.30000.json#record-95d450c5-0190-401b-8b8b-aeb050167553","tags":[]},{"id":"poem-f33630b53cd6edca95e61e5c","title":"思越人·渚莲枯","author":"孙光宪","dynasty":"五代","verses":["渚莲枯，宫树老，长洲废萧条。","想象玉人空处所，月明独上溪桥。","经春初败秋风起，江兰绿蕙愁死。","一片风流伤心地，魂销目断西子。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-8-juan.json#record-40","tags":[]},{"id":"poem-f33b36c1b1bbb5ff30e0fdca","title":"献花铺唐相李德裕谪海南道此有山女献花因以名之次壁间韵","author":"李纲","dynasty":"宋","verses":["我亦乘桴向海涯，无人复献雨中花。","却愁春梦归吴越，茗饮浓斟薄荷芽。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.90000.json#record-1daedec9-69e3-461c-a29f-d8abaf33f848","tags":[]},{"id":"poem-f33c1833fde3d50f492b6b23","title":"赋得花庭雾","author":"太宗皇帝","dynasty":"唐","verses":["兰气已熏宫，新橤半粧丛。","色含轻重雾，香引去来风。","拂树浓舒碧，萦花薄蔽红。","还当杂行雨，髣髴隐遥空。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.0.json#record-53cabac3-3558-4bcb-8845-9ebe1c3eb562","tags":[]},{"id":"poem-f340c21a5225019b8e5c59fe","title":"櫂歌行","author":"徐坚","dynasty":"唐","verses":["櫂女饰银钩，新妆下翠楼。","霜丝青桂檝，兰栧紫霞舟。","水落金陵曙，风起洞庭秋。","扣舷过曲浦，飞帆越回流。","影入桃花浪，香飘杜若洲。","洲长殊未返，萧散云霞晚。","日下大江平，烟生归岸远。","岸远闻潮波，争途游戏多。","因声赵津女，来听采菱歌。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.5000.json#record-605462fe-3bcc-4503-a9ef-22ae16636dd2","tags":["洞庭湖"]},{"id":"poem-f34a685f079d44259382ded4","title":"春秋战国门 鲍叔","author":"周昙","dynasty":"唐","verses":["忠臣祝寿吐嘉词，鲍叔临轩酒一巵。","安不忘危臣所愿，愿思危困必无危。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.40000.json#record-266b9e36-04c2-4248-a719-7a631d3baf11","tags":[]},{"id":"poem-f350749491875d096dc425f6","title":"句  其七","author":"刘望之","dynasty":"宋","verses":["南县烧畬早，西溪落涨初。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.120000.json#record-f749a2f5-f9a1-438e-b8d4-213a22bb1ec8","tags":[]},{"id":"poem-f352bdab44b0151be3a7250e","title":"南原望汉宫","author":"司空曙","dynasty":"唐","verses":["荒原空有汉宫名，衰草茫茫雉堞平。","连雁下时秋水在，行人过尽暮烟生。","西陵歌吹何年绝，南陌登临此日情。","故事悠悠不可问，寒禽野水自纵横。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.15000.json#record-550d7a0c-eb74-46c2-8bd8-7e837642be87","tags":[]},{"id":"poem-f35405910bdc97ad1a37352f","title":"寄徐晦","author":"张籍","dynasty":"唐","verses":["鄠陂鱼美酒偏浓，不出琴斋见雪峰。","应胜昨来趋府日，簿书床上乱重重。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.20000.json#record-c4ff8d39-cbac-431a-aaac-f12a80f1f99c","tags":[]},{"id":"poem-f370fcd5528bd1774ba26dee","title":"胡捣练","author":"徐田臣《杀狗记》","dynasty":"元","verses":["(小生上)吾命窘，自嗟呀，哥哥同甚念头差？赶出此身无依倚，使人今夜落谁家？万事不由人计较，一生都是命安排。","我孙荣被哥赶逐出来，没处安身，不免到王大姑店中借住几时，再作区处。","此间已是了，婆婆有么？(净)呀！官人请坐。","(小生)有坐。","(净)官人家居何处？姓甚名谁？。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-1733","tags":[]},{"id":"poem-f37d597a83ec99374b4a0cb3","title":"节妇吟寄东平李司空师道","author":"张籍","dynasty":"唐","verses":["君知妾有夫，赠妾双明珠。","感君缠绵意，系在红罗襦。","妾家高楼连苑起，良人执戟明光里。","知君用心如日月，事夫誓拟同生死。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.20000.json#record-7f57cb22-3bda-45c2-b5cb-aeaa10a3376d","tags":["坚贞","女子","乐府","新乐府辞"]},{"id":"poem-f38123d800a490d14afa05b4","title":"除夜作","author":"高适","dynasty":"唐","verses":["旅馆寒灯独不眠，客心何事转凄然。","故乡今夜思千里，愁鬓明朝又一年。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.10000.json#record-26d3dbf4-bc0f-4b19-ab8d-fce4d9e2af10","tags":["岁月","孤独","思乡","春节"]},{"id":"poem-f3875b742471374fb22ae803","title":"十亩之间","author":"佚名","dynasty":"先秦","verses":["十亩之间兮，桑者闲闲兮，行与子还兮。","十亩之外兮，桑者泄泄兮，行与子逝兮。"],"enabled":true,"collection":"诗经","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/诗经/shijing.json#record-110","tags":[]},{"id":"poem-f38b9c34c471463c8c6744be","title":"晓","author":"徐夤","dynasty":"唐","verses":["水尽铜龙滴渐微，景阳钟动梦魂飞。","潼关鸡唱促归骑，金殿烛残求御衣。","窗下寒机犹自织，梁间栖燕欲双飞。","羲和晴耸扶桑辔，借与寰瀛看早晖。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.40000.json#record-9fe7f7a5-d731-4c61-a355-d372e2503401","tags":[]},{"id":"poem-f391f51ee06351e91d214b34","title":"独醒午坐","author":"王琮","dynasty":"宋","verses":["小槽停溜务厅闲，幕府文书省却难。","竟日裴回无俗意，祇因竹外有秋山。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.210000.json#record-fab22fd5-7333-4e15-a337-a720306b7922","tags":[]},{"id":"poem-f3986633e919f6459315876b","title":"绝句","author":"杜甫","dynasty":"唐","verses":["两个黄鹂鸣翠柳，一行白鹭上青天。","窗含西岭千秋雪，门泊东吴万里船。"],"enabled":true,"collection":"千家诗","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/蒙学/qianjiashi.json#record-絕句","tags":[]},{"id":"poem-f39b7a9e9e61946224a2080e","title":"石城晓","author":"李贺","dynasty":"唐","verses":["月落大隄上，女垣栖乌起。","细露湿团红，寒香解夜醉。","女牛渡天河，柳烟满城曲。","上客留断缨，残蛾鬬双绿。","春帐依微蝉翼罗，横茵突金隐体花。","帐前轻絮鹤毛起，欲说春心无所似。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.20000.json#record-9f1b8b1c-d6f4-4117-91e5-e012a5c39f8d","tags":[]},{"id":"poem-f39d10e5e3cb055eec62e691","title":"前腔","author":"高明《蔡伯喈琵琶记》","dynasty":"元","verses":["满纸云烟，说尽离愁千万千。","想那层楼十二，有个人人，倚着危阑。","他望归期，数飞雁，阻关山，见书如见经年面。","(合前)。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-5136","tags":[]},{"id":"poem-f3a349923cb93e2d67006ebc","title":"桓","author":"佚名","dynasty":"先秦","verses":["绥万邦，屡丰年。天命匪解，桓桓武王。保有厥士，于以四方，克定厥家。于昭于天，皇以间之。"],"enabled":true,"collection":"诗经","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/诗经/shijing.json#record-293","tags":[]},{"id":"poem-f3a64ee8a6c5288cc7e28c2a","title":"前腔","author":"柯丹邱《荆钗记》","dynasty":"元","verses":["［生］因科举，欲赴都，免不得抛妻弃母。","千思百虑，母老妻娇，却教谁为主？既岳翁惜寡怜孤，这分明爱枝惜树。","且自随机应变。","慎勿推阻。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-8118","tags":[]},{"id":"poem-f3a69f36e089d5c2fd52f426","title":"颂古三十一首  其三○","author":"释玿","dynasty":"宋","verses":["佛手驴脚生缘，生缘驴脚佛手。","李公醉倒街头，元是张公吃酒。","黄龙山里老婆禅，恰似河阳新妇丑。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.120000.json#record-4bd50575-513f-4253-acbf-7c45cab311d6","tags":[]},{"id":"poem-f3ab365c468a791decabe571","title":"临江仙·闻道彤庭森宝仗","author":"张抡","dynasty":"宋","verses":["闻道彤庭森宝仗，霜风逐雨驱云。","六龙扶辇下青冥。","香随鸾扇远，日射赭袍明。","帘卷天街人隘路，满城喜望清尘。","欢声催起岭梅春。","欲知天意好，昨夜月华新。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.8000.json#record-887","tags":[]},{"id":"poem-f3b4f0c7c6d5f6a86e2e52e3","title":"川拨棹","author":"杨景贤","dynasty":"元","verses":["更好笑哩，好着我笑微微，一个汉木雕成两个腿。","见几个回回，舞着面旌旗，阿剌剌口里不知道甚的，妆着鬼，人多我看不仔细。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-10110","tags":[]},{"id":"poem-f3b8196c855117e1c0c3f7e3","title":"别洞庭维谅上人","author":"皎然","dynasty":"唐","verses":["白云关我不关他，此物留君情最多。","情著春风生橘树，归心不怕洞庭波。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.45000.json#record-e7808f40-425c-47f1-9d9b-61e5658bea45","tags":["洞庭湖"]},{"id":"poem-f3bafa8a63422e0b421fecc1","title":"秋千词","author":"王建","dynasty":"唐","verses":["长长丝绳紫复碧，袅袅横枝高百尺。","少年儿女重秋千，盘巾结带分两边。","身轻裙薄易生力，双手向空如鸟翼。","下来立定重系衣，复畏斜风高不得。","傍人送上那足贵，终赌鸣珰鬬自起。","回回若与高树齐，头上宝钗从堕地。","眼前争胜难为休，足踏平地看始愁。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.15000.json#record-db5e7031-fe00-4693-a3e0-ed08debf7dec","tags":[]},{"id":"poem-f3c23a41a6294862d9247a72","title":"诉衷情·闲中一首醉时歌","author":"张抡","dynasty":"宋","verses":["闲中一首醉时歌。","此乐信无过。","阳春自来寡和，谁与乐和。","言不尽，意何多。","且蹉跎。","功名莫问，富贵休言，到底如何。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.8000.json#record-972","tags":[]},{"id":"poem-f3c9aef2e67002038a546173","title":"菩萨蛮·为陈其年题照","author":"纳兰性德","dynasty":"清","verses":["晓寒瘦著西南月，丁丁漏箭余香咽。","春已十分宜，东风无是非。","蜀魂羞顾影，玉照斜红冷。","谁唱《后庭花》，新年忆旧家。"],"enabled":true,"collection":"纳兰词","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/纳兰性德/纳兰性德诗集.json#record-181","tags":[]},{"id":"poem-f3cb3435c49c4f3fe27432ee","title":"摘鬓间白髪有感","author":"李纲","dynasty":"宋","verses":["吾生足忧患，未老头已白。","鬓间垂素丝，揽镜聊一摘。","星星去虽欣，种种鲜还戚。","颇愁日增多，尽拔复何益。","追思少年时，绿髪光且泽。","森然茂云松，岂谓少堪惜。","自从多病后，脱落露广额。","蒲柳姿易衰，日与风霜迫。","萧萧不胜梳，扰扰仅盈搦。","安能上指冠，常恐吹堕帻。","年来涉艰虞，更复非夙昔。","奔驰动万里，漂泊继三谪。","从横蹈危机，侈哆困烦啧。","交游莫援手，仇怨惟下石。","素标宜满头，斑鬓未为逼。","何年运河车，溯补泥丸宅。","华颠复变鬒，去作烟霞客。","憔悴楚江滨，岁晚将何获。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.90000.json#record-434e3eec-bc18-4a26-901c-1895aa5a6a33","tags":[]},{"id":"poem-f3cbc07170e1d3a30336bb31","title":"送流人","author":"司空曙","dynasty":"唐","verses":["闻说南中事，悲君重窜身。","山村枫子鬼，江庙石郎神。","童稚留荒宅，图书托故人。","青门好风景，为尔一沾巾。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.15000.json#record-6be2f191-b7c7-4861-9212-88a2eb7a5723","tags":[]},{"id":"poem-f3d5856c274577798cbf0b2f","title":"岳麓山道林二寺行","author":"杜甫","dynasty":"唐","verses":["玉泉之南麓山殊，道林林壑争盘纡。","寺门高开洞庭野，殿脚插入赤沙湖。","五月寒风冷佛骨，六时天乐朝香炉。","地灵步步雪山草，僧宝人人沧海珠。","墖劫宫墙壮丽敌，香厨松道清凉俱。","连花交响共命鸟，金牓双回三足乌。","方丈涉海费时节，悬圃寻河知有无。","暮年且喜经行近，春日兼蒙暄暖扶。","飘然斑白身奚适，傍此烟霞茅可诛。","桃源人家易制度，橘洲田土仍膏腴。","潭府邑中甚淳古，太守庭内不喧呼。","昔遭衰世皆晦迹，今幸乐国养微躯。","依止老宿亦未晚，富贵功名焉足图。","久为野客寻幽惯，细学何颙免兴孤。","一重一掩吾肺腑，山鸟山花吾友于。","宋公放逐曾题壁，物色分留与老夫。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.10000.json#record-d893768c-c581-4169-8d36-636e552ec09e","tags":["洞庭湖"]},{"id":"poem-f3dd1d4a3e3000f23c086292","title":"前腔","author":"高明《蔡伯喈琵琶记》","dynasty":"元","verses":["糠和米，本是两倚依，谁人簸扬你作两处飞？一贱与一贵，好似奴家共夫婿，终无见期。","丈夫，你便是米么，米在他方没寻处。","奴便是糠么，怎的把糠救得人饥馁？好似儿夫出去，怎的教奴，供给得公婆甘旨？(不吃放碗介)(唱)。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-5074","tags":[]},{"id":"poem-f3edc98c038468f88a3d41b4","title":"颂古七十六首  其三六","author":"释士珪","dynasty":"宋","verses":["殿上唤来先应诺，不知业识太茫茫。","虽然功德已成就，争奈当初不放光。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.90000.json#record-f5b9ff82-911e-475e-be29-cfff9ec89474","tags":[]},{"id":"poem-f3f53f6ef986f012f58fae8c","title":"上平江徐侍郎十绝句  其九","author":"曾协","dynasty":"宋","verses":["拥麾仗节往来频，抚字澄清处处新。","想见兹辰介眉寿，遥应驩动几州人。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.120000.json#record-fa165949-74c3-4c83-a0a0-e8c0a2bd11e3","tags":[]},{"id":"poem-f40a6332dd89a553ff7a7957","title":"同河南李少尹毕员外宅夜饮时洛阳告捷遂作春酒歌","author":"高适","dynasty":"唐","verses":["故人美酒胜浊醪，故人清词合风骚。","长歌满酌惟吾曹，高谈正可挥麈毛。","半醉忽然持蟹螯，洛阳告捷倾前后。","武侯腰间印如斗，郎官无事时饮酒。","桮中绿蚁吹转来，瓮上飞花拂还有。","前年持节将楚兵，去年留司在东京。","今年复拜二千石，盛夏五月西南行。","彭门劒门蜀山里，昨逢军人刦夺我。","到家但见妻与子，赖得饮君春酒数十桮，不然令我愁欲死。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.10000.json#record-399d7586-1d9c-491f-b854-2f7b61b27980","tags":[]},{"id":"poem-f4116089931b981473adf032","title":"文彧少卿文山郎中交好深至二纪已余暌别数年二子长逝奉使岭表涂次南康吊孙氏之孤于其家睹文彧手书于僧室慷慨悲叹留题此诗","author":"徐铉","dynasty":"宋","verses":["吊孙家虚座吊诸孤，张叟僧房见手书。","二纪欢游今若此，满衣零泪欲何如。","腰间金印从如斗，镜里霜华已满梳。","珍重远公应笑我，尘心唯此未能除。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.0.json#record-0b35b07d-f179-4876-b483-dc0ad9929a2e","tags":[]},{"id":"poem-f412a4bf5c6505a14f07f556","title":"题耿处士林亭","author":"喻坦之","dynasty":"唐","verses":["身向闲中老，生涯本豁然。","草堂山水下，渔艇鸟花边。","窥井猨兼鹿，啼林鸟杂蝉。","何时人事了，依此亦高眠。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.40000.json#record-0a93b883-a286-4cff-b440-0d0a38749ef6","tags":[]},{"id":"poem-f4294d4dcf64ef1456997db3","title":"寄归","author":"赵嘏","dynasty":"唐","verses":["三年踏尽化衣尘，只见长安不见春。","马过雪街天未曙，客迷关路泪空频。","桃花坞接啼猿寺，野竹庭通画鹢津。","早晚相酬身事了，水边归去一闲人。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.30000.json#record-d4f8653d-f4d9-4668-9df6-b164483cc8ea","tags":[]},{"id":"poem-f42bad0ec6559f58890f5ba8","title":"答白公","author":"徐凝","dynasty":"唐","verses":["高景争来草木头，一生心事酒前休。","山公自是仙人侣，携手醉登城上楼。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.25000.json#record-824804d2-ec32-44ac-9f21-94dcbdb6023b","tags":[]},{"id":"poem-f42f40490af2164765d7001a","title":"偈颂（幷序○序为南岳齐己撰） 四十八","author":"居遁","dynasty":"唐","verses":["在梦那知梦是虚，觉来方觉梦中无。","迷时恰似梦中士，悟后还同睡起夫。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.55000.json#record-5419a820-25a2-4603-a207-b629f494641b","tags":["衡山"]},{"id":"poem-f43143ba21f1a2928e9b8da4","title":"送韦员外还京","author":"崔峒","dynasty":"唐","verses":["十年离乱后，此去若为情。","春晚香山绿，人稀豫水清。","野陂看独树，关路逐残莺。","前殿朝明主，应怜白发生。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.15000.json#record-e3026b4a-e2e5-47f8-8497-ae73399bda6b","tags":[]},{"id":"poem-f43a28dfa0ef129431cc4a3a","title":"送远曲","author":"张籍","dynasty":"唐","verses":["吴门向西流水长，水长柳暗烟茫茫。","行人送客各惆怅，话离叙别倾清觞。","吟丝竹，鸣笙簧，酒酣性逸歌猖狂。","行人告我挂帆去，此去何时返故乡。","殷勤振衣两相嘱，世事近来还浅促。","愿君看取吴门山，带雪经春依旧绿。","行人行处求知亲，送君去去徒酸辛。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.20000.json#record-5639c076-ff59-4271-bfff-731b0ab3b719","tags":[]},{"id":"poem-f43a29f7c658d099b5be26ad","title":"思妇吟","author":"苏拯","dynasty":"唐","verses":["秋风雁又归，边信一何早。","揽衣出门望，落叶满长道。","一从秉箕箒，十载孤怀抱。","可堪日日醉宠荣，不说思君令人老。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.40000.json#record-58279968-e510-4460-9a4c-d807cb0845e4","tags":[]},{"id":"poem-f44c52e14fd07eb8b946259c","title":"戏张道人不饮酒","author":"颜荛","dynasty":"唐","verses":["言自云山访我来，每闻奇秘觉叨陪。","吾师不饮人间酒，应待流霞即举杯。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.40000.json#record-dafcc512-e764-422d-9b9a-e6f12ef1b23b","tags":[]},{"id":"poem-f44ef4f5d9ef924627aa590b","title":"送酒与邵尧夫因戏之","author":"司马光","dynasty":"宋","verses":["林下虽无忧可消，许由闻说挂空瓢。","请君呼取孟光饮，共插花枝煮药苗。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.30000.json#record-ce173b2b-b06d-4b3b-901c-3b65b2c62701","tags":[]},{"id":"poem-f45e24081c7e760d94bb85a7","title":"长门怨","author":"刘得仁","dynasty":"唐","verses":["争得一人闻此怨，长门深夜有妍姝。","早知雨露翻相悮，只插荆钗嫁匹夫。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.30000.json#record-8d95be93-4b1d-477d-9e26-773a89fb8588","tags":[]},{"id":"poem-f4641be4af5312b7b1a5ed90","title":"凤凰台","author":"罗隐","dynasty":"唐","verses":["昔云丹穴凤，翔集高台端。","（同前。","）。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.55000.json#record-65a9b2ba-30bc-476c-922a-40add4f526a5","tags":[]},{"id":"poem-f47b803c8a40de50bc248c80","title":"玉楼春·别后不知君远近","author":"欧阳修","dynasty":"宋","verses":["别后不知君远近。","触目凄凉多少闷。","渐行渐远渐无书，水阔鱼沈何处问。","夜深风竹敲秋韵。","万叶千声皆是恨。","故欹单枕梦中寻，梦又不成灯又尽。"],"enabled":true,"collection":"宋词三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/宋词三百首.json#record-175","tags":["宋词三百首"]},{"id":"poem-f4812ff0bd6ae3521ca769df","title":"·","author":"魏璞","dynasty":"唐","verses":["。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.50000.json#record-961972d9-99b3-4c7f-b4e7-b5c255f15664","tags":[]},{"id":"poem-f481c3f90626592de5060bdb","title":"春早选寓长安二首 一","author":"薛能","dynasty":"唐","verses":["疎拙自沈昏，长安岂是村。","春非闲客事，花在五侯门。","道僻惟忧祸，诗深不敢论。","扬雄若有荐，君圣合承恩。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.30000.json#record-88877dbb-3e4d-40a8-8626-3a13951718c0","tags":[]},{"id":"poem-f482d654f5dca1c14c01ce1e","title":"永明山居诗（六十九首） 六十七","author":"延寿","dynasty":"唐","verses":["数朝兴废狂风过，千载荣枯掣电飞，早向权门思息意，莫于尘世自沈机。","一条水引闲花出，万里云随独鹤归。","最要身安成大道，免教他后始知非。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.55000.json#record-5a337703-7bf3-43c7-ad11-f4ed0c3cb025","tags":[]},{"id":"poem-f48934ec90efa4d022851a06","title":"燕雁","author":"汪宗臣","dynasty":"宋","verses":["秋来春去雁宾熟，秋去春来燕子忙。","寒暑自分人事信，不须禽类互炎凉。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.240000.json#record-76014e2c-3f07-4272-a4fe-9c23125c9291","tags":[]},{"id":"poem-f490480a611ca7bb37854174","title":"宿鄠郊赠罗处士","author":"李洞","dynasty":"唐","verses":["川静星高栎已枯，南山落石水声麤。","白云钓客窗中宿，卧数嵩峰听五湖。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.40000.json#record-f10da4e2-dc93-4c65-931e-6adb79f74a33","tags":[]},{"id":"poem-f4909075343516dd492ae302","title":"度破讷沙二首 一","author":"李益","dynasty":"唐","verses":["眼见风来沙旋移，经年不省草生时。","莫言塞北无春到，总有春来何处知。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.15000.json#record-6be79308-f67c-4d92-80eb-a4f206bc5b83","tags":[]},{"id":"poem-f4929f7c9bdbcf45228c36ae","title":"句  其一","author":"许玠","dynasty":"宋","verses":["宇宙双蓬鬓。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.210000.json#record-ad599a3d-cd06-4c18-867f-baf35fa8a58e","tags":[]},{"id":"poem-f4b6d12019ca5327d6d23357","title":"四园竹·浮云护月","author":"周邦彦","dynasty":"宋","verses":["浮云护月，未放满朱扉。","鼠摇暗壁，萤度破窗，偷入书帏。","秋意浓，闲伫立、庭柯影里。","好风襟袖先知。","夜何其。","江南路绕重山，心知谩与前期。","奈向灯前堕泪，肠断萧娘，旧日书辞。","犹在纸。","雁信绝，清宵梦又稀。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.4000.json#record-406","tags":[]},{"id":"poem-f4be99874244dc228e389789","title":"野田黄雀行","author":"贯休","dynasty":"唐","verses":["高树风多，吹尔巢落。","深蒿叶暖，宜尔依泊。","莫近鸮类，蛛网亦恶。","饮野田之清水，食野田之黄粟。","深花中睡，𡋯土里浴。","如此即全胜啄太仓之谷，而更穿人之屋。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.45000.json#record-28f892da-d936-4767-a397-5a2273fe1c36","tags":[]},{"id":"poem-f4c78aecd73175ecdd5e9ac2","title":"江行","author":"纳兰性德","dynasty":"清","verses":["木落江已空，清辉澹鸥鹭。","不见系缆石，寒潮没瓜步。","帆移清枫林，人归白沙渡。","似有山猿啼，窈然潇湘暮。"],"enabled":true,"collection":"纳兰词","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/纳兰性德/纳兰性德诗集.json#record-225","tags":[]},{"id":"poem-f4ccf17bf9a5210e0f14f395","title":"哭左偃（题拟）","author":"王操","dynasty":"唐","verses":["堂亲垂白日，稚子欲行时。","（见《增修诗话总龟》卷四引《雅言杂录》。","）（按：王操入宋后诗存者尚多，兹不备录。","）。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.55000.json#record-35d6ba2a-dc45-4b4e-bcc9-5aca45d051a3","tags":[]},{"id":"poem-f4d5f8325825e5101fd2d8a6","title":"寄卢式","author":"项斯","dynasty":"唐","verses":["到处久南望，未知何日回。","寄书频到海，得梦忽闻雷。","岭日当秋暗，蛮花近腊开。","白身居瘴疠，谁不惜君才。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.30000.json#record-78c85b2e-80de-4b1f-957d-7d36d726e2c8","tags":[]},{"id":"poem-f4d7aac7783fd84bca2f8449","title":"昔昔盐二十首 恒歛千金笑","author":"赵嘏","dynasty":"唐","verses":["玉颜恒自歛，羞出镜台前。","早惑阳城客，今悲华锦筵。","从军人更远，投喜鹊空传。","夫壻交河北，迢迢路几千。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.30000.json#record-a6b50da8-c9e3-4606-9053-44c1cb81e657","tags":[]},{"id":"poem-f4ddc6324b533eff3d0fd856","title":"浣溪沙·雨点春山入翠眉","author":"向子𬤇","dynasty":"宋","verses":["雨点春山入翠眉。","一ь杨柳作腰肢。","语音娇软带儿痴。","犹省当来求识面，隔帘清唱倒琼彝。","真成相见说当时。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.6000.json#record-800","tags":[]},{"id":"poem-f4e2237ee21a822b2ba68334","title":"早春会王逵主人得蓬字","author":"李端","dynasty":"唐","verses":["今年华鬓色，半在故人中。","欲写无穷恨，先期一醉同。","绿丛犹覆雪，红萼已凋风。","莫负归山契，君看陌上蓬。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.15000.json#record-c119d5d1-3bd8-40af-ae71-a9f5a990ce14","tags":[]},{"id":"poem-f4e5ae7def1ff00c22c5501a","title":"遥和尘外上人与陆澧夜集山寺问湼槃义兼陆生文卷","author":"皎然","dynasty":"唐","verses":["共是竹林贤，心从贝叶传。","说经看月喻，开卷爱珠连。","清净遥城外，萧疎古塔前。","应随北山子，高顶枕云眠。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.45000.json#record-d2c31d26-e45b-441c-aad5-54f2d24801be","tags":[]},{"id":"poem-f4e8f8e4e1e7c57b8fd3997a","title":"游寺","author":"李咸用","dynasty":"唐","verses":["无家身自在，时得到莲宫。","秋觉暑衣薄，老知尘世空。","幽情怜水石，野性任萍蓬。","是处堪闲坐，与僧行止同。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.35000.json#record-16df96bc-83b9-4212-baac-a828c15caf97","tags":[]},{"id":"poem-f4fcfbbb6a978d030a5fd1ba","title":"偈颂（幷序○序为南岳齐己撰） 三十三","author":"居遁","dynasty":"唐","verses":["毫厘有差千里隔，刹那一悟祖师齐。","玄微须向玄中体，道用还教道者知。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.55000.json#record-318b2b48-17df-4d7f-84e5-28f64ff66fa9","tags":["衡山"]},{"id":"poem-f4fd398604cd99c4d8c8605b","title":"四换头","author":"柯丹邱《荆钗记》","dynasty":"元","verses":["贼泼贱闭嘴，数黑论黄讲甚的？我是你什么人？［旦］是娘。","［净］恰又来，娘言语怎违逆？颐父母颜情却是礼。","［旦］顺父母颜情，人之大礼。","话不投机，教人怎随？富豪贪恋，贫穷见弃，惹得傍人讲是非。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-8086","tags":[]},{"id":"poem-f500da8dcfa8810e2862edbb","title":"雪二首 一","author":"司空曙","dynasty":"唐","verses":["乐游春苑望鹅毛，宫殿如星树似毫。","漫漫一川横渭水，太阳初出五陵高。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.15000.json#record-e072c7f0-1d16-4941-8ded-6703c9f66b44","tags":[]},{"id":"poem-f505a8205a20bff29b8a8344","title":"偈颂七十一首  其八","author":"释了惠","dynasty":"宋","verses":["两手指天地，周行步更多。","可怜黄面老，螃蟹落汤锅。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.210000.json#record-fce7ea92-b9fb-4bca-8bb6-21d485212d44","tags":[]},{"id":"poem-f506fc8850c9eeafba43df5a","title":"巫山高","author":"沈佺期","dynasty":"唐","verses":["巫山高不极，合沓状奇新。","暗谷疑风雨，阴崖若鬼神。","月明三峡曙，潮满九江春。","为问阳台客，应知入梦人。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.5000.json#record-9d06a3cc-bddb-49e9-a80d-5b3adc3de3e1","tags":[]},{"id":"poem-f50e1e1644899bb90af56f10","title":"过庆宝寺","author":"司空曙","dynasty":"唐","verses":["黄叶前朝寺，无僧寒殿开。","池晴龟出曝，松暮鹤飞回。","古井碑横草，阴廊画杂苔。","禅宫亦销歇，尘世转堪哀。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.15000.json#record-3ba99fff-5db9-4e38-9f05-6e4466a2c150","tags":[]},{"id":"poem-f511928c99811da5f9d3dc26","title":"道勾漏山灵宝观窃睹两朝御书谨成古风","author":"李纲","dynasty":"宋","verses":["抱疴卧云海，夙夕负深恐。","寛恩听旋归，何啻丘岳重。","问津勾漏山，散策宝圭洞。","群峰罗翠屏，环合无缺空。","游仙契初心，幽赏恊清梦。","却来观宸章，宝气腾䗖𬟽。","真行杂草隶，笔势极翔动。","大小飞白书，飘洒萦舞凤。","恭惟睿智姿，多能本天纵。","妙迹藏名山，俾与万世共。","林峦增炳焕，神物劳护拥。","惜无深岩屋，荫覆示崇奉。","何当鸠良材，为葺倾压栋。","天弧不指狼，中原胡马閧。","九庙未奠居，臣子衘愤痛。","岂知炎荒中，奎画得瞻讽。","至哉慱大言，粟麦因异种。","天常及诸佛，一一资妙供。","窃于翰藻间，窥见神心用。","源流此中来，基本中兴宋。","稽首归琅函，斐然成善颂。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.90000.json#record-53313a18-82e1-4199-a632-e8c6ad6683f3","tags":[]},{"id":"poem-f51c3acd571d5ffa840e9cb0","title":"望江南・忆江南·江南月","author":"王琪","dynasty":"宋","verses":["江南月，清夜满西楼。","云落开时冰吐鉴，浪花深处玉沈钩。","圆缺几时休。","星汉迥，风露入新秋。","丹桂不知摇落恨，素娥应信别离愁。","天上共悠悠。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.0.json#record-850","tags":[]},{"id":"poem-f53071d1e51636963eaed454","title":"春日思景仁","author":"司马光","dynasty":"宋","verses":["去歳洛城中，嬉游处处同。","从离崿岭北，常梦潩泉东。","草遶春街碧，花繁夕市红。","临风默惆怅，想像白眉翁。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.30000.json#record-f9170f37-432b-4fc7-994e-82c5f89ec01e","tags":[]},{"id":"poem-f531ab3ab2a443ce69743399","title":"渔父","author":"屈原","dynasty":"先秦","verses":["屈原既放，游于江潭，行吟泽畔，颜色憔悴，形容枯槁。渔父见而问之曰：“子非三闾大夫与？何故至于斯？”屈原曰：“举世皆浊我独清，众人皆醉我独醒，是以见放。”","渔父曰：“圣人不凝滞于物，而能与世推移。世人皆浊，何不淈其泥而扬其波？众人皆醉，何不𫗦其糟而歠其醨？何故深思高举，自令放为？”","屈原曰：“吾闻之，新沐者必弹冠，新浴者必振衣安能以身之察察，受物之汶汶者乎？宁赴湘流，葬于江鱼之腹中。安能以皓皓之白，而蒙世俗之尘埃乎？”","渔父莞尔而笑，鼓枻而去。","乃歌曰：“沧浪之水清兮，可以濯吾缨。沧浪之水浊兮，可以濯吾足。”遂去，不复与言。"],"enabled":true,"collection":"楚辞","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/楚辞/chuci.json#record-24","tags":[]},{"id":"poem-f53ee4b2bc63c87535ccc852","title":"润州水楼","author":"杨凌","dynasty":"唐","verses":["归心不可留，雪桂一丛秋。","叶雨空江月，萤飞白露洲。","野蝉依独树，水郭带孤楼。","遥望山川路，相思万里游。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.15000.json#record-61b7672c-004e-42c9-815d-6b311e1492b6","tags":[]},{"id":"poem-f54114ef4fdfdaff853ff914","title":"长安晓望寄崔补阙","author":"包何","dynasty":"唐","verses":["迢递山河拥帝京，参差宫殿接云平。","风吹晓漏经长乐，柳带晴烟出禁城。","天净笙歌临路发，日高车马隔尘行。","自怜久滞诸生列，未得金闺籍姓名。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.10000.json#record-f5a1b0dc-92fd-41ad-aa63-3bb3b4c772f7","tags":[]},{"id":"poem-f543b7a8d5c9dde2351dbc79","title":"含笑花五首  其二","author":"李纲","dynasty":"宋","verses":["玉质犹披翡翠裳，温泉浴罢蔼天香。","回眸百媚嫣然处，羞死三千红粉粧。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.90000.json#record-95216ade-2ab9-4e03-96a2-150856f4ff61","tags":[]},{"id":"poem-f544689b2fcef9ecc9dc8a0f","title":"蓼莪","author":"佚名","dynasty":"先秦","verses":["蓼蓼者莪，匪莪伊蒿。哀哀父母，生我劬劳。","蓼蓼者莪，匪莪伊蔚。哀哀父母，生我劳瘁。","瓶之罄矣，维罍之耻。鲜民之生，不如死之久矣。无父何怙？无母何恃？出则衔恤，入则靡至。","父兮生我，母兮鞠我。抚我畜我，长我育我，顾我复我，出入腹我。欲报之德。昊天罔极！","南山烈烈，飘风发发。民莫不谷，我独何害！南山律律，飘风弗弗。民莫不谷，我独不卒！"],"enabled":true,"collection":"诗经","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/诗经/shijing.json#record-201","tags":[]},{"id":"poem-f565c5659b13ff4f215f528f","title":"减字木兰花·风鬟雾鬓","author":"周邦彦","dynasty":"宋","verses":["风鬟雾鬓。","便觉蓬莱三岛近。","水秀山明。","缥缈仙姿画不成。","广寒丹桂。","岂是夭桃尘俗世。","只恐乘风。","飞上琼楼玉宇中。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.4000.json#record-515","tags":[]},{"id":"poem-f565e58e21cd675d99bea5bd","title":"天下乐","author":"萧德祥《小孙屠》","dynasty":"元","verses":["一种相思聚两眉，因娇卖酒。","此妇人生得肌莹琼台片雪，脸如红杏鲜妍。","见它不觉惹起鸳鸯之恨，欲求鸾凤之欢。","说道：若得落籍除名，愿为夫妇。","如今不免多将些金帛，前往衙前，寻那旧契张面前，去那本官根前说则个。","(末上白)昨晚那孙必达所托之事，已自从本官根前覆过了。","今日特来这里，说与那人知道。","(末见生介)(生)张面前，昨日所托之事如何？(末)昨晚已曾本官根前说过了当，请哥哥来。","(生)小生不多，先有银子两锭，上下使用。","哥根前小生当自重重拜谢！(末)不须如此。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-8586","tags":[]},{"id":"poem-f570fe4b56b6c5c3d668a7e8","title":"善哉行 其二","author":"曹操","dynasty":"汉","verses":["自惜身薄祜，夙贱罹孤苦。","既无三徙教，不闻过庭语。","其穷如抽裂，自以思所怙。","虽怀一介志，是时其能与！","守穷者贫贱，惋叹泪如雨。","泣涕于悲夫，乞活安能睹？","我愿于天穷，琅邪倾侧左。","虽欲竭忠诚，欣公归其楚。","快人由为叹，抱情不得叙。","显行天教人，谁知莫不绪。","我愿何时随？此叹亦难处。","今我将何照于光曜？释衔不如雨。"],"enabled":true,"collection":"曹操诗集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/曹操诗集/caocao.json#record-19","tags":[]},{"id":"poem-f571d819c4f8b906f964897e","title":"德升尚书出示岁除用韦苏州韵前后二篇及两郎属和粲然盈轴赏叹之余有感于中亦輙次韵书山居一时事  其二","author":"綦崇礼","dynasty":"宋","verses":["儿童喜时节，老大悲齿髪。","流光难把玩，百年如倐忽。","夜灯犹故岁，晨燎已端月。","回首名宦途，常虞骇机发。","今来对青山，安坐见春物。","得失孰多少，且使寸心歇。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.90000.json#record-8c7f4ac0-9150-4f90-ab60-3ea5b2e2fce4","tags":[]},{"id":"poem-f5738fb8fb68af599245a3be","title":"偈颂（幷序○序为南岳齐己撰） 五十六","author":"居遁","dynasty":"唐","verses":["杉松直拔映峰峦，一色长青道者看。","四气盛衰无变异，岂同凡木有多般。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.55000.json#record-2a0cfdb7-869a-4960-89da-f36e12c25df2","tags":["衡山"]},{"id":"poem-f575427adddde5f2b8645d87","title":"玉真观寻赵尊师不遇","author":"姚鹄","dynasty":"唐","verses":["羽客朝元昼掩扉，林中一径雪中微。","松阴遶院鹤相对，山色满楼人未归。","尽日独思风驭返，寥天几望野云飞。","凭高目断无消息，自醉自吟愁落晖。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.30000.json#record-29cc3989-63f7-48c0-af2d-f1494809de6f","tags":[]},{"id":"poem-f578404f61d92c3c382f0019","title":"试院中闻初平别头预上舍选作诗二章以贻之  其二","author":"华镇","dynasty":"宋","verses":["龙头本是我青毡，寂寞风流数百年。","素业久惭吾未振，遗芳今喜汝能传。","九光瑞日才披雾，千里修途要著鞭。","竹素纪名男子事，莫令风味愧吾先。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.60000.json#record-59ab2496-f503-439a-9785-ddee51c4e32f","tags":[]},{"id":"poem-f578f1992f843ad4462eb500","title":"西","author":"徐夤","dynasty":"唐","verses":["密云郊外已回秋，日下崦嵫景懒收。","秦帝城高坚似铁，李斯书上曲如钩。","宁惟东岳凌天秀，更有长庚瞰曙流。","见说山傍偏出将，犬戎降尽复何愁。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.40000.json#record-8987a0f6-a89c-4224-a462-67cb9e1a7282","tags":[]},{"id":"poem-f58174bb11b9473395c96fcb","title":"祝英台近·采幽香","author":"吴文英","dynasty":"宋","verses":["采幽香，巡古苑，竹冷翠微路。","斗草溪根，沙印小莲步。","自怜两鬓清霜，一年寒食，又身在、云山深处。","昼闲度。","因甚天也悭春，轻阴便成雨。","绿暗长亭，归梦趁风絮。","有情花影阑干，莺声门径，解留我、霎时凝伫。"],"enabled":true,"collection":"宋词三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/宋词三百首.json#record-195","tags":["宋词三百首"]},{"id":"poem-f58741f8a3200a1ad072dd45","title":"柳梢青·品雅风流","author":"曾觌","dynasty":"宋","verses":["品雅风流，端端正正，堪人怜惜。","因甚新来，眉儿不展，愁情如织。","倡条冶叶无情，犹为他、千思万忆。","据恁当初，真心实意，如何亏得。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.8000.json#record-351","tags":[]},{"id":"poem-f587d45a720122f02e114fe6","title":"琮师送至城月驿戏成两绝句以答其意  其二","author":"李纲","dynasty":"宋","verses":["好住湖岩摄此心，有缘终会有知音。","梁谿老去孤峰顶，月白风清难更寻。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.90000.json#record-f37b14ca-ff66-44de-8533-0133ccb338ba","tags":[]},{"id":"poem-f58e60080f33d7741d663674","title":"怀赵府录","author":"释居简","dynasty":"宋","verses":["知义称仲子，义岂仲子明。","康章果何事，其如通国人。","国人眼芒羊，眇视终不亲。","悠悠鹿为马，扰扰丹成青。","轲岂好辩哉，隠若不得平。","斥矫如斥羊，子孝俾孝信。","高风既偃草，雄辩如建瓴。","真固易为赝，赝亦难逃真。","至今百世下，粲粲日与星。","向来宣城掾，赵擅梁楚声。","束书甫言归，议者纷而纭。","番腾巧如织，萋菲骈相新。","老我若病瘖，不觉勇自鸣。","掾自仙源来，世袭清流盟。","家法凛雪霜，厥绪方振振。","诸父相颉颃，渭阳更轮囷。","佞贤决雄雌，霄壤与渭泾。","轲死虽无传，此舌死不泯。","不与智者道，此道谁商评。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.180000.json#record-27591a8d-a5ab-461f-8cd2-68924d7d12b9","tags":[]},{"id":"poem-f5961e7ed04eee8c295054a9","title":"观《山海图》二首 其二","author":"张祜","dynasty":"唐","verses":["何人笔思狂，一壁尽沧浪。","日月明丹拱，烟云起画梁。","山岚开晓色，海气动秋光。","岛踞鳌睛大，沙行鳄齿长。","粉波明百越，黛点簇三湘。","讵作无图意，空迷造化乡。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.50000.json#record-424f9a6e-8057-408b-91be-4942133d6609","tags":[]},{"id":"poem-f59fd3b6000bbfa02b952f47","title":"次琼管后三日忽奉德音恩许自便感涕之余赋诗见志  其一","author":"李纲","dynasty":"宋","verses":["此身飘堕到沧溟，谁谓君王念贾生。","黄帋再蒙题姓字，丹书特为削刑名。","山林老去何其幸，萍梗追思却自惊。","天地恩寛难报德，试从今日数归程。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.90000.json#record-6dd0ff5d-e645-4179-a71f-378a16ec48a3","tags":[]},{"id":"poem-f5ba75031ab7e5732d712750","title":"次姜尧章赠诗卷中韵  其五","author":"陈造","dynasty":"宋","verses":["眼青节食事，日耐饥雷吼。","兹幸陪众后，酒巵甫到口。","不离寂寞滨，径造无何有。","问津归有期，尚许寻盟否。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.150000.json#record-edb20123-7f87-4bf1-8d60-0b4e3472a333","tags":[]},{"id":"poem-f5c201cae88d786dad5a753e","title":"兵要望江南 占六壬第二十八（京本列第十七○四十五首） 三十五","author":"易静","dynasty":"唐","verses":["课惊怖，日上细寻推。","辰巳太冲加日上，若逢蛇雀见凶危，复手也如之。","（大吉加日，宜急去，不可住，辰上见太冲，夜必有风雨，若神后太乙加日辰，夜有贼盗。","旺相必见，无气则不见。","）。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.55000.json#record-e657157b-7b10-45d2-ad5c-376615c5dbc1","tags":[]},{"id":"poem-f5d2196eda9ee073da259fa5","title":"送友人下第归省","author":"殷遥","dynasty":"唐","verses":["君此卜行日，高堂应梦归。","莫将和氏泪，滴著老莱衣。","岳雨连河细，田禽出麦飞。","到家调膳后，吟好送斜晖。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.5000.json#record-88a6a7aa-6a5b-4ce9-9b51-9187cf3a5a76","tags":[]},{"id":"poem-f5ffc51822ec15b985251b28","title":"元日早朝行","author":"鲍溶","dynasty":"唐","verses":["乾元发生春为宗，盛德在天斗建东。","东方岁星大明宫，南山喜气摇晴空。","望云五等舞万玉，献寿一声出千峰。","文章垂彩礼乐正，太白下直旌旗红。","旌旗不断春风前，直如朱绳非尔妍。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.25000.json#record-1cd4d6dd-cfc6-44aa-8af3-30400208b3db","tags":[]},{"id":"poem-f61b126a3630cdd9ed49be9e","title":"赋得听松声","author":"刘得仁","dynasty":"唐","verses":["庭际微风动，高松韵自生。","听时无物乱，尽日觉神清。","强与幽泉竝，翻嫌细雨幷。","拂空增鹤唳，过牖合琴声。","况复当秋暮，偏宜在月明。","不知深涧底，萧瑟有谁听。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.30000.json#record-6777f6f1-7d62-44e7-b785-0fca3e34bb05","tags":[]},{"id":"poem-f627b5436f13636de01a43d8","title":"画马篇","author":"高适","dynasty":"唐","verses":["君侯枥上骢，貌在丹青中。","马毛连钱蹄铁色，图画光辉骄玉勒。","马行不动势若来，权奇蹴踏无尘埃。","感兹绝代称妙手，遂令谈者不容口。","麒麟独步自可珍，驽骀万匹知何有，终未如他枥上骢。","载华毂，聘飞鸿，荷君剪拂与君用，一日千里如旋风。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.10000.json#record-e94f7b4c-7e68-4d8b-81b3-053539a689d8","tags":[]},{"id":"poem-f62a207910a99cd634581a81","title":"画眉郎・好女儿·雪絮雕章","author":"贺铸","dynasty":"宋","verses":["雪絮雕章。","梅粉华妆。","小芒台、榧机罗湘素，鼓铜蟾砚滴，金雕琴写，玉燕钗梁。","五马徘徊长路，漫非意、凤求凰。","认兰情、自有怜才处，似题桥贵客，栽花潘令，真画眉郎。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.2000.json#record-871","tags":[]},{"id":"poem-f631a2098e0b21bca294dbab","title":"和长历赋纸阁用王介甫韵","author":"刘跂","dynasty":"宋","verses":["顶还平直得中方，肯作僧庵半夜床。","脱帽不忧风栗烈，炽炉仍助日苍凉。","赏音正自鸣琴便，宴坐何辞问疾妨。","我有陟厘三百幅，御冬真欲倒归囊。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.60000.json#record-da6e56ee-bff8-4acd-a960-88e609e84b8a","tags":[]},{"id":"poem-f639e17309d2f0520b496963","title":"七娘子·山围水绕高唐路","author":"向子𬤇","dynasty":"宋","verses":["山围水绕高唐路。","恨密云、不下阳台雨。","雾阁云窗，风亭月户。","分明携手同行处。","而今不见生尘步。","但长江、无语东流去。","满地落花，漫天飞絮。","谁知总是离愁做。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.2000.json#record-138","tags":["长江"]},{"id":"poem-f6489202e7fed17fe9bd36e3","title":"九章·抽思","author":"屈原","dynasty":"先秦","verses":["心郁郁之忧思兮，独永叹乎增伤。","思蹇产之不释兮，曼遭夜之方长。","悲秋风之动容兮，何回极之浮浮。","数惟荪之多怒兮，伤余心之忧忧。","愿摇起而横奔兮，览民尤以自镇。","结微情以陈词兮，矫以遗夫美人。","昔君与我诚言兮，曰黄昏以为期。","羌中道而回畔兮，反既有此他志。","憍吾以其美好兮，览余以其修姱。","与余言而不信兮，盖为余而造怒。","愿承闲而自察兮，心震悼而不敢。","悲夷犹而冀进兮，心怛伤之憺憺。","兹历情以陈辞兮，荪详聋而不闻。","固切人之不媚兮，众果以我为患。","初吾所陈之耿著兮，岂至今其庸亡？","何独乐斯之謇謇兮？","愿荪美之可光。","望三王以为像兮，指彭咸以为仪。","夫何极而不至兮，故远闻而难亏。","善不由外来兮，名不可以虚作。","孰无施而有报兮，孰不实而有获？","少歌曰：与美人抽思兮，并日夜而无正。","憍吾以其美好兮，敖朕辞而不听。","倡曰：有鸟自南兮，来集汉北。","好姱佳丽兮，牉独处此异域。","惸茕独而不群兮，又无良媒在其侧。","道卓远而日忘兮，愿自申而不得。","望北山而流涕兮，临流水而太息。","望孟夏之短夜兮，何晦明之若岁？","惟郢路之辽远兮，魂一夕而九逝。","曾不知路之曲直兮，南指月与列星。","愿径逝而未得兮，魂识路之营营。","何灵魂之信直兮，人之心不与吾心同！","理弱而媒不通兮，尚不知余之从容。","乱曰：长濑湍流，溯江潭兮。","狂顾南行，聊以娱心兮。","轸石崴嵬，蹇吾愿兮。","超回志度，行隐进兮。","低徊夷犹，宿北姑兮。","烦冤瞀容，实沛徂兮。","愁叹苦神，灵遥思兮。","路远处幽，又无行媒兮。","道思作颂，聊以自救兮。","忧心不遂，斯言谁告兮。"],"enabled":true,"collection":"楚辞","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/楚辞/chuci.json#record-16","tags":[]},{"id":"poem-f64aaa31a8a41d482846a178","title":"中元前一夕枕上偶成","author":"纳兰性德","dynasty":"清","verses":["酒醒池塘耿不眠，帐纹漠漠隔轻烟。","溪风到竹初疑雨，秋月如弓渐满弦。","残梦远经吹角戍，明河长亘衣天。","哀蛩饯晓浑多事，也似严更古驿边。"],"enabled":true,"collection":"纳兰词","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/纳兰性德/纳兰性德诗集.json#record-226","tags":[]},{"id":"poem-f64b9209f9706e166d85bd90","title":"与次道集贤谏议元素翰林赴冲卿枢密谏议见招宴会同赋","author":"苏颂","dynasty":"宋","verses":["江淮罢郡许归朝，台阁重来鬓渐凋。","内禁群英容接武，西枢元弼记尝僚。","当年已绝坐中礼，此日犹蒙客右招。","衰病无堪还自慰，交游相继上层霄。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.30000.json#record-ca64f443-275f-4178-9e99-d0f582d8e4d4","tags":[]},{"id":"poem-f64e3155da71d0333d3c8e08","title":"题云居上寺","author":"王益","dynasty":"唐","verses":["[支]公禅诵处，绝顶共登攀。","日色千峰里，钟声万壑间。","[暮]猿吟砌近，沙鸟傍溪闲。","一迳[堪]藜杖，行行独下山。","（见《金石萃编》卷一百五。","）（缺文据《续古文苑》卷四补。","《房山石经题记汇编》首字不缺。","）（〖1〗石刻诗次王潜诗后。","原题曰「同前」。","下署「男益上」。","与吉逾诗序所称「息益」合。","〖2〗王益，原作吉益。","为王潜之子，详前吉逾条附考。","诸书录石刻。","此诗收于王潜诗之次，署「男益上」。","）。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.50000.json#record-4e12a790-abd6-46d0-ba84-636f4931ccc2","tags":[]},{"id":"poem-f65216ac6a942e09f7882d6d","title":"醉落魄・一斛珠·无言哽噎","author":"赵佶","dynasty":"宋","verses":["无言哽噎。","看灯记得年时节。","行行指月行行说。","愿月常圆，休要暂时缺。","今年华市灯罗列。","好灯争柰人心别。","人前不敢分明说。","不忍抬头，羞见旧时月。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.6000.json#record-529","tags":[]},{"id":"poem-f6556fbcdbfeca8dae455bdb","title":"金山","author":"张栻","dynasty":"宋","verses":["万顷洪涛里，巍然阅古今。","云烟三岛接，花木四时深。","乱石维舟住，西风倚槛吟。","朝宗知不断，凄切此时心。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.150000.json#record-b064106e-87fd-4736-b5c1-2b3c145a8468","tags":[]},{"id":"poem-f65c85dcc24aa25c461de84b","title":"奉和崔司马游云门寺","author":"孙逖","dynasty":"唐","verses":["系马清溪树，禅门春气浓。","香台花下出，讲坐竹间逢。","觉路山童引，经行谷鸟从。","更言穷寂灭，回策上南峰。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.5000.json#record-27740b09-a53f-40ec-8e6c-ec678db07f41","tags":[]},{"id":"poem-f65f4a2cbe93e45d5693241f","title":"虞美人草","author":"释居简","dynasty":"宋","verses":["君恩如海海不深，妾义如铁利断金。","舍生取义我所欲，忍死织室羞同心。","春姿忽作秋蓬委，一寸刚明曾不死。","明年原上野花繁，一枝自托华风起。","袅袅娉娉不成艳，态度浅深生色染。","向人欲诉却无言，寂寞千年恨谁掩。","芳郊游女宛转歌，倚春拍手看婆娑。","露晞初日枝头坠，犹有君王别时泪。","翻刘覆楚知几何，大风竟作还乡歌。","淮南区区欲为帝，淮阴堂堂贺陈狶。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.180000.json#record-4c44487c-fcb3-4c93-85d7-6b42edcfed5f","tags":[]},{"id":"poem-f66db30aa9c746a9c1942522","title":"长宁公主东庄侍宴","author":"李峤","dynasty":"唐","verses":["别业临青甸，鸣銮降紫霄。","长筵鹓鹭集，仙管凤凰调。","树接南山近，烟含北渚遥。","承恩咸已醉，恋赏未还镳。"],"enabled":true,"collection":"千家诗","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/蒙学/qianjiashi.json#record-長寧公主東莊侍宴","tags":[]},{"id":"poem-f67289826a7972cf62c56b46","title":"清平乐·留人不住","author":"晏几道","dynasty":"宋","verses":["留人不住。","醉解兰舟去。","一棹碧涛春水路。","过尽晓莺啼处。","渡头杨柳青青。","枝枝叶叶离情。","此后锦书休寄，画楼云雨无凭。"],"enabled":true,"collection":"宋词三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/宋词三百首.json#record-25","tags":["宋词三百首"]},{"id":"poem-f67812ef8448671d1849fc7d","title":"闺怨","author":"王昌龄","dynasty":"唐","verses":["闺中少妇不曾愁，春日凝妆上翠楼。","忽见陌头杨柳色，悔教夫壻觅封侯。"],"enabled":true,"collection":"唐诗三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/唐诗三百首.json#record-4ac3f099-73da-43e8-a4e5-1dbbd9427491","tags":["唐诗三百首","妇女","春天","七言绝句","闺怨"]},{"id":"poem-f691ccb01807a09e98e2bb71","title":"南乡子·直柱倚冰弦","author":"高观国","dynasty":"宋","verses":["直柱倚冰弦。","曾见胡儿马上弹。","却笑琵琶风韵古，溅溅。","想像湘妃水一帘。","塞恨曲中传。","两折琴丝费玉纤。","不似江南风月好，厌厌。","拍手齐看舞袖边。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.6000.json#record-401","tags":[]},{"id":"poem-f6a058c815b73ebccdcd86e3","title":"十玄谈（幷序） 转位归（《大正》本、《偈颂》作「回机」）","author":"常察","dynasty":"唐","verses":["湼槃城里尚犹危，陌路相逢没了（《大正》本作「没定」、《偈颂》作「勿定」）期。","权挂垢衣云是佛，却装珍御复名谁？木人夜半穿靴去，石女天明戴帽归。","万古碧潭空界月，再三涝（《大正》本、《偈颂》作「捞」）漉始应知。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.55000.json#record-53857dec-e3bf-440f-bb1f-eb904c62b113","tags":[]},{"id":"poem-f6a0bbbc07bad5cb7681886c","title":"赠侯山人","author":"熊孺登","dynasty":"唐","verses":["一见清容惬素闻，有人传是紫阳君。","来时玉女裁春服，翦破湘山几片云。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.25000.json#record-940eed81-f316-4ce4-91ec-6133b3dc0053","tags":[]},{"id":"poem-f6a7e86994a08117d97998ec","title":"菩萨蛮·乌丝画作回纹纸","author":"纳兰性德","dynasty":"清","verses":["乌丝画作回纹纸，香煤暗蚀藏头字。","筝雁十三双，输他作一行。","相看仍似客，但道休相忆。","索性不还家，落残红杏花。"],"enabled":true,"collection":"纳兰词","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/纳兰性德/纳兰性德诗集.json#record-187","tags":[]},{"id":"poem-f6aa24b09b94646d2a6cb8e9","title":"过王濬暮","author":"明皇帝","dynasty":"唐","verses":["吴国分牛斗，晋室命龙骧。","受任敌已灭，策勋名不彰。","居美未尽善，矜功徒自伤。","长戟今何在？孤坟此路傍。","不观松柏茂，空余荆棘场。","叹嗟悬劒陇，谁识梦刀祥。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.0.json#record-6ae53f2c-48fa-464c-8453-de7b2434c716","tags":[]},{"id":"poem-f6b2947a130e85806550d43b","title":"京口江际弄水","author":"徐铉","dynasty":"宋","verses":["退公求静独临川，扬子江南二月天。","百尺翠屏甘露阁，数帆晴日海门船。","波澄濑石寒如玉，草接汀苹绿似烟。","安得乘槎更东去，十洲风外弄潺湲。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.0.json#record-f405cfe1-cdaa-413a-ab44-cd7fb3beddd6","tags":[]},{"id":"poem-f6bb37b23b8f94951a78788d","title":"更漏子·旧欢娱","author":"顾敻","dynasty":"五代","verses":["旧欢娱，新怅望，拥鼻含颦楼上。","浓柳翠，晚霞微，江鸥接翼飞。","帘半卷，屏斜掩，远岫参差迷眼。","歌满耳，酒盈樽，前非不要论。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-7-juan.json#record-36","tags":[]},{"id":"poem-f6c5894268cbdd5e453e633e","title":"夜到渔家","author":"张籍","dynasty":"唐","verses":["渔家在江口，潮水入柴扉。","行客欲投宿，主人犹未归。","竹深村路远，月出钓船稀。","遥见寻沙岸，春风动草衣。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.20000.json#record-f3df89b4-1a24-40b5-b668-1348f73d22c6","tags":["抒情","游子","写人"]},{"id":"poem-f6c96b2d2449afae93a80204","title":"清平乐·金风细细","author":"晏殊","dynasty":"宋","verses":["金风细细。","叶叶梧桐坠。","绿酒初尝人易醉。","一枕小窗浓睡。","紫微朱槿花残。","斜阳却照阑干。","双燕欲归时节，银屏昨夜微寒。"],"enabled":true,"collection":"宋词三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/宋词三百首.json#record-161","tags":["宋词三百首"]},{"id":"poem-f6ce691d998aa4fb7e676adc","title":"访落","author":"佚名","dynasty":"先秦","verses":["访予落止，率时昭考。于乎悠哉，朕未有艾。将予就之，继犹判涣。","维予小子，未堪家多难。绍庭上下，陟降厥家。休矣皇考，以保明其身。"],"enabled":true,"collection":"诗经","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/诗经/shijing.json#record-286","tags":[]},{"id":"poem-f6d13421b943250ceb980748","title":"河传·柳拖金缕","author":"孙光宪","dynasty":"五代","verses":["柳拖金缕，着烟笼雾，蒙蒙落絮。","凤皇舟上楚女，妙舞，雷喧波上鼓。","龙争虎战分中土，人无主，桃叶江南渡。","襞花笺，艳思牵。","成篇，官娥相与传。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-7-juan.json#record-47","tags":[]},{"id":"poem-f6d4faf969ff273cd8b2a3b2","title":"满江红·秋满漓源","author":"张孝祥","dynasty":"宋","verses":["秋满漓源，瘴云净、晓山如簇。","动远思、空江小艇，高丘乔木。","策策西风双鬓底，晖晖斜日朱栏曲。","试侧身、回首望京华，迷南北。","思归梦，天边鹄。","游宦事，蕉中鹿。","想一年好处，砌红堆绿。","罗帕分柑霜落齿，冰磐剥芡珠盈掬。","倩春纤、缕鲙捣香齑，新𥬠熟。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.6000.json#record-224","tags":[]},{"id":"poem-f6d6578a79c9b4e314fa7da1","title":"巴江夜猨","author":"马戴","dynasty":"唐","verses":["日饮巴江水，还啼巴岸边。","秋声巫峡断，夜影楚云连。","露滴青枫树，山空明月天。","谁知泊船者，听此不能眠。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.30000.json#record-ad24d16d-abc1-4cf1-be80-0cea602bd5df","tags":[]},{"id":"poem-f6da6f29b238dbe0a8f97a0f","title":"舟过孤山","author":"王琮","dynasty":"宋","verses":["寂寞梅花处士坟，竹围岩脚一泉深。","隃瞻翠辇曾游处，水钥年年护绿阴。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.210000.json#record-7f5b578f-7ce0-4893-a658-87b82e03e3dc","tags":[]},{"id":"poem-f6dbf46c20d0fae28a9f23e5","title":"献汉南樊尚书","author":"孟郊","dynasty":"唐","verses":["天下昔崩乱，大君识贤臣。","众木尽摇落，始见竹色真。","兵势走山岳，阳光潜埃尘。","心开玄女符，面缚清波人。","异俗既从化，浇风亦归淳。","自公理斯郡，寒谷皆变春。","旗影卷赤电，劒锋匣青鳞。","如何嵩高气，作镇楚水滨。","云镜忽开霁，孤光射无垠。","乃知寻常鉴，照影不照神。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.20000.json#record-d23cf818-caff-4858-b6f8-d7f178987574","tags":[]},{"id":"poem-f6e43c18bb1be3df9eddbc48","title":"庚子八月八日再游东山寺","author":"韩缜","dynasty":"宋","verses":["蜀师当日戍黄金，此地由来险阻深。","漾水东流自纡直，泰山北望正嵚崟。","凉风肃物初秋意，膏泽愆期旦昼阴。","同是天涯未归客，荒烟斜日正登临。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.30000.json#record-6fb47550-4eed-4d50-8f94-9ba28eb41107","tags":["泰山"]},{"id":"poem-f6f1bc47ff2b0ce41cb4587e","title":"粉蝶儿·一箭和风","author":"史浩","dynasty":"宋","verses":["一箭和风，秾熏许多春意。","闹蛾儿、满城都是。","向深闺，争翦碎、吴绫蜀绮。","点妆成，分明是、粉须香翅。","玉容似花，全胜故园桃李。","最相宜、鬓云秋水。","怎教他，却去与、庄周同睡。","愿年年，伴星球、烂游灯市。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.8000.json#record-101","tags":[]},{"id":"poem-f6f411330f88631f715c125d","title":"离歌辞五首  其二","author":"徐铉","dynasty":"宋","verses":["朝日城南路，旌旗照绿芜。","使君何处去，桑下觅罗敷。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.0.json#record-d34491df-fd4b-49bc-97e1-730cf5bcbed4","tags":[]},{"id":"poem-f6f77c653eee54f566266688","title":"李先辈擢第东归有赠送","author":"赵嘏","dynasty":"唐","verses":["金榜前头无是非，平人分得一枝归。","正怜日煖云飘路，何处宴回风满衣？","门掩长淮心更远，渡连芳草马如飞。","茂陵自笑犹多病，空有书斋在翠微。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.30000.json#record-f690b93a-075c-47b6-8ced-efb42f55cb90","tags":[]},{"id":"poem-f6f782c83cbd9de78938ea54","title":"颂古三十一首  其九","author":"释原妙","dynasty":"宋","verses":["幸然无事鼓风涛，激起洪波万丈高。","直得浑家都浸杀，至今平地浪滔滔。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.240000.json#record-445f4225-6d06-41c6-9e96-53495ec33aa0","tags":[]},{"id":"poem-f6f7f1d6743b9a47279c161e","title":"采桑子·严霜拥絮频惊起","author":"纳兰性德","dynasty":"清","verses":["严霜拥絮频惊起，扑面霜空。","斜汉朦胧。","冷逼毡帷火不红。","香篝翠被浑闲事，回首西风。","何处疏钟，一穗灯花似梦中。"],"enabled":true,"collection":"纳兰词","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/纳兰性德/纳兰性德诗集.json#record-101","tags":[]},{"id":"poem-f702ca7b6dd21d59a1affc53","title":"早秋即事寄冯使君","author":"贯休","dynasty":"唐","verses":["金脉火初微，开门竹杖随。","此身全是病，今日更嗔谁。","落叶峥嵘处，诸峰爽拔时。","唯思棠树下，高论入圆伊。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.45000.json#record-4fafd02d-6d57-4fa9-88db-067a89caa8ba","tags":[]},{"id":"poem-f705e853a2b290ab41cc9d5e","title":"颂 二","author":"绍修","dynasty":"唐","verses":["欲识解脱道，诸法不相到。","眼耳绝见闻，声色闹浩浩。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.55000.json#record-80aada41-9d65-4e3f-83fb-a20da48489e1","tags":[]},{"id":"poem-f70982beb35ba35fb0fc5cf5","title":"兵要望江南 《周易》占候第二十六（三十七首） 四","author":"易静","dynasty":"唐","verses":["入他国，我即论为（辛本、川本作「其」）宾。","若是他来攻我寨，我为主（辛本、川本作「宾」）者汝为宾（辛本、川本作「尊」），此理合天文。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.55000.json#record-b15bd5c3-1751-4168-8188-a769ae993c10","tags":[]},{"id":"poem-f70aaabadebe425891578996","title":"兵要望江南 占六壬第二十八（京本列第十七○四十五首） 六","author":"易静","dynasty":"唐","verses":["看岁月，冲破时（辛本、川本、京本作「下」）推之。","上将行年居此位（辛本、川本、京本作「下」），师行（辛本、京本作「侯」）身必有凶危，禳厌始无亏。","（月将加所得之时，看支干上见魁罡星者主惊溃。","将帅行年上见魁罡者宜禳之。","）。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.55000.json#record-ba6df73c-7f11-4349-b541-4d022c50eadc","tags":[]},{"id":"poem-f7118cbfa0493335070bafe3","title":"过故人庄","author":"孟浩然","dynasty":"唐","verses":["故人具鸡黍，邀我至田家。","绿树村边合，青山郭外斜。","开筵面场圃，把酒话桑麻。","待到重阳日，还来就菊花。"],"enabled":true,"collection":"唐诗三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/唐诗三百首.json#record-9309205e-1d08-4a7b-99ef-4a05a9ee4370","tags":["唐诗三百首","生活","田园","友情","初中古诗","五言律诗","山","七年级上册(课外)","四年级上册"]},{"id":"poem-f71d278b099189aa2abd0380","title":"题净名院二绝  其二","author":"王十朋","dynasty":"宋","verses":["谷中有月露蛾眉，水织珠帘更绝奇。","满目峰峦观未尽，有僧携纸觅题诗。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.120000.json#record-c2cd533c-c6b7-40c2-8fd5-1b24dd3a68dd","tags":[]},{"id":"poem-f7218579b21f189bfaef98e3","title":"菩萨蛮·新寒中酒敲窗雨","author":"纳兰性德","dynasty":"清","verses":["新寒中酒敲窗雨，残香细袅秋情绪。","才道莫伤神，青衫湿一痕。","无聊成独卧，弹指韶光过。","记得别伊时，桃花柳万丝。"],"enabled":true,"collection":"纳兰词","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/纳兰性德/纳兰性德诗集.json#record-194","tags":[]},{"id":"poem-f7246d76d789dde2f67b3ac2","title":"南楼","author":"刘似祖","dynasty":"宋","verses":["雁过危栏字字愁，谁将官柳系行舟。","不知东去大江水，流出西川第几州。","汉上仅遗孤垒在，斗边忽见数星浮。","夜深莫问当年事，不是祢衡鹦鹉洲。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.210000.json#record-730c39bb-e9af-4a2e-a6c0-305596469151","tags":[]},{"id":"poem-f72b841df05b5f2cb713fdf2","title":"洋州三十景 筼筜谷","author":"鲜于侁","dynasty":"宋","verses":["晖晖蓝田山，山下多绿玉。","安得结茅茨，林间许容足。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.30000.json#record-85854fcf-b966-41bd-88b0-183cfe0b99ec","tags":[]},{"id":"poem-f73309fc7df816182cac58d7","title":"香迳分韵得江字","author":"赵文","dynasty":"宋","verses":["一亭寒碧中，四面空无窗。","种荷未有花，清意已满腔。","小坐梅树下，我亦青油幢。","晚来蝉声歇，静境热自降。","清风与明月，造物无对桩。","闲者恣吟取，如瓢分大江。","欲归尚未肯，雨湿烟钟撞。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.240000.json#record-5f310fe4-5257-4c9b-8645-f82f1fd89db5","tags":[]},{"id":"poem-f73aa00415da9841fc37366a","title":"和韦开州盛山十二首 梅溪","author":"张籍","dynasty":"唐","verses":["自爱新梅好，行寻一径斜。","不教人扫石，恐损落来花。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.20000.json#record-5dc1daca-91ed-4733-a4b4-b20c3243d375","tags":[]},{"id":"poem-f7433edb27707041ab5a7270","title":"上司空员外","author":"李洞","dynasty":"唐","verses":["禅心高卧似疎慵，诗客经过不厌重。","藤杖几携量碛雪，玉鞭曾把数嵩峰。","夜眠古巷当城月，秋直清曹入省钟。","禹凿故山归未得，河声暗老两三松。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.40000.json#record-9ed6b88f-5f36-488a-94e9-7bf067da6a56","tags":[]},{"id":"poem-f748a3bce6cda22e63717cda","title":"句","author":"刘吉","dynasty":"唐","verses":["一箭不中鹄，五湖归钓鱼。","（《赠隐者》。","见《宋诗纪事》卷三引《历代吟谱》。","按《全唐诗》卷七百九十五作张茔诗句。","云见地志。","）（《增修诗话总龟》卷一引《丛苑》、《宋朝事实类苑》卷五五引《杨文公谈苑》幷载刘吉此二句诗，并云其「有诗三百首，目为《钓鼇集》，徐铉为序。","其首篇《赠隐者》，……人多诵之」。","《全唐诗》所收张茔，应张莹，《淳熙三山志》卷二、卷三四收此二句为其诗。","二句似验刘作为近是。","）。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.50000.json#record-b3761e77-cfbc-4499-b6c1-392733bf4b27","tags":[]},{"id":"poem-f751486b877a7f4420173a52","title":"同李著作纵题尘外上人院","author":"皎然","dynasty":"唐","verses":["百缘唯有什公瓶，万法但看一字经。","从遣鸟喧心不动，任教香醉境常冥。","莲花天昼浮云卷，贝叶宫春好月停。","禅伴欲邀何著作，空音宜向夜中听。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.45000.json#record-3d6c53ef-dfc3-41c7-aad3-36ef946709fa","tags":[]},{"id":"poem-f75223f0887dae6b43e42bc6","title":"采桑子·谁翻乐府凄凉曲","author":"纳兰性德","dynasty":"清","verses":["谁翻乐府凄凉曲。","风也萧萧，雨也萧萧，瘦尽灯花又一宵。","不知何事萦怀抱，醒也无聊，醉也无聊，梦也何曾到谢桥。"],"enabled":true,"collection":"纳兰词","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/纳兰性德/纳兰性德诗集.json#record-10","tags":[]},{"id":"poem-f75d14516432fc94346d5890","title":"虞美人·荒城又见重阳到","author":"晁补之","dynasty":"宋","verses":["荒城又见重阳到。","狂醉还吹帽。","人生开口笑难逢。","何况良辰一半，别离中。","平台朱履登高处。","犹自怀人否。","且簪黄菊满头归。","惟有此花风韵、似年时。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.4000.json#record-233","tags":[]},{"id":"poem-f76199df48444401765b07a5","title":"挽王学正  其二","author":"叶大年","dynasty":"宋","verses":["遗文脍炙在吾乡，赋罢谁能少荐扬。","声迹有妻先蝶梦，行藏无子付洴方。","云萝烟蔓新泉宅，秋月春花旧野堂。","交倡丝牋真翰墨，几人知为宝巾箱。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.120000.json#record-1c928ce6-749f-44f6-8f2f-e064ec15b0f5","tags":[]},{"id":"poem-f76749448f575e3bb32ab980","title":"过鲁太师庙","author":"华镇","dynasty":"宋","verses":["汉家循吏得民深，素业流风尚可寻。","愧在盛时操短刃，远来邻壤效鸣琴。","敢论异事追前事，所喜仁心契本心。","振辔再经驯雉境，一瞻道庙想徽音。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.60000.json#record-b447e006-003b-483a-b650-3f1e78d8470c","tags":[]},{"id":"poem-f770414e54f454a2c158f90d","title":"千里思","author":"李端","dynasty":"唐","verses":["凉州风月美，遥望居延路。","泛泛下天云，青青缘塞树。","燕山苏武上，海岛田横住。","更是草生时，行人出门去。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.15000.json#record-de1797c7-0c10-4d76-aac3-68dbfbf82b77","tags":[]},{"id":"poem-f7714f909489722bf62696c3","title":"偈颂六十七首  其一五","author":"释原妙","dynasty":"宋","verses":["天关久锁不开容，日夜滂沱鼓黑风。","愤性一槌俱击碎，顶门迸出一轮红。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.240000.json#record-0fde72c7-8df4-4445-946f-c59282a2c8bb","tags":[]},{"id":"poem-f77b2d75beaebc3443ec8ee4","title":"前腔","author":"柯丹邱《荆钗记》","dynasty":"元","verses":["［老旦］黄河尚有澄清日，岂可人无得运时？［旦］皇都得意，那时好个风流婿。","［生］我寒儒显赫门楣，太岳翁传扬名誉。","［合前］。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-8123","tags":[]},{"id":"poem-f77ccb2cdeac604a9be5f536","title":"上元应制","author":"王淇","dynasty":"宋","verses":["雪消华月满仙台，万烛当楼宝扇开。","双凤云中扶辇下，六鳌海上驾山来。","镐京春酒沾周宴，汾水秋风陋汉才。","一曲升平人尽乐，君王又进紫霞杯。"],"enabled":true,"collection":"千家诗","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/蒙学/qianjiashi.json#record-上元應制","tags":[]},{"id":"poem-f78070b829dfae427ce65184","title":"观浙江涛","author":"徐凝","dynasty":"唐","verses":["浙江悠悠海西绿，惊涛日夜两翻覆。","钱塘郭里看潮人，直至白头看不足。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.25000.json#record-994f5da5-7097-49f3-9225-8f268fca39da","tags":[]},{"id":"poem-f782e1fc5f76842ab16b27ee","title":"古意二首 一","author":"崔国辅","dynasty":"唐","verses":["玉笼薰绣裳，著罢眠洞房。","不能春风里，吹却兰麝香。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.5000.json#record-fd485fea-3025-4224-b8fb-769d56b6cf9a","tags":[]},{"id":"poem-f7978f8431248d470d3af529","title":"浣溪沙·花渐凋疏不耐风","author":"孙光宪","dynasty":"五代","verses":["花渐凋疏不耐风，画帘垂地晚堂空，堕阶萦藓舞愁红。","腻粉半沾金靥子，残香犹暖绣熏笼，蕙心无处与人同。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-7-juan.json#record-39","tags":[]},{"id":"poem-f79ceb5bd547a994446874b7","title":"射策后作","author":"卢肇","dynasty":"唐","verses":["射策明时愧不才，敢期青律变寒灰。","晴怜断雁侵云去，暖见醯鸡傍酒来。","箭发尚忧杨叶远，愁生只恐杏花开。","曲江春浅人游少，尽日看山醉独回。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.30000.json#record-03242a8b-2d7e-4677-bb24-24708db0f371","tags":[]},{"id":"poem-f79df84d5fa0c32a272c225c","title":"白石潭秋霁作","author":"周繇","dynasty":"唐","verses":["潭心烟雾破斜晖，殷殷雷声隔翠微。","崖蹙盘涡翻蜃窟，滩吹白石上渔矶。","陵风舴艋讴哑去，出水鸬鹚薄泊飞。","秋霁更谁同此望，远钟时见一僧归。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.35000.json#record-ee815980-f7ce-4628-bd99-698fff712372","tags":[]},{"id":"poem-f7a4ec115530d5186bd9cc18","title":"春日和卢使君幼平开元寺听妙奘上人讲","author":"皎然","dynasty":"唐","verses":["仁圣垂文在，虚空日月悬。","陵迟追哲匠，宗旨发幽诠。","法受诸侯请，心教四子传。","春生雪山草，香下棘林天。","顾我从今日，闻经悟宿缘。","凉山万里去，应为教犹偏。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.45000.json#record-443e078d-95b3-4650-846b-7de1cd41e6a7","tags":[]},{"id":"poem-f7ac96ee8b831a6b692a25e3","title":"游泾川琴溪","author":"武平一","dynasty":"唐","verses":["环潭澄晓色，叠嶂照秋影。","幽致欣所逢，纷虑自兹屏。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.5000.json#record-793b94f3-f7f9-477f-b588-ab464328959c","tags":[]},{"id":"poem-f7ae6300ef5d0ceb692b9a48","title":"六么序","author":"无名氏《宦门子弟错立身》","dynasty":"元","verses":["一意随它去，情愿为路岐。","管甚么抹土搽灰，折莫擂鼓吹笛，点拗收拾。","更温习几本杂剧，问甚么妆孤扮末诸般会，更那堪会跳索扑旗。","只得同欢共乐同鸳被，冲州撞府，求衣觅食。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-308","tags":[]},{"id":"poem-f7b38e87daafd9bb1d987ccd","title":"腊月二日携家城东观梅夜归  其二","author":"张栻","dynasty":"宋","verses":["元自阳春无间断，何人能识化工心。","梅边把酒日近午，鸟语风微花气深。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.150000.json#record-de48243d-f81b-4c36-81ec-5fda9d7ffbaf","tags":[]},{"id":"poem-f7b3e13880454ff267ba2485","title":"览史","author":"皎然","dynasty":"唐","verses":["黄绮皆皓发，秦时隐商山。","嘉谋匡帝道，高步游天关。","不爱珪组绁，却思林壑还。","放歌长松下，日与孤云闲。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.45000.json#record-0f885a40-7601-4ae1-b885-afa5562f07c5","tags":[]},{"id":"poem-f7b4a6016b9d4b8afcd78426","title":"唐享昊天乐 第十","author":"则天皇后","dynasty":"唐","verses":["肃肃祀典，邕邕礼秩。","三献已周，九成斯毕。","爰撤其俎，载迁其实。","或升或降，惟诚惟质。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.0.json#record-20286700-303e-4d6f-96a8-39e528e2a9df","tags":[]},{"id":"poem-f7c06de72495ad2af42b07c5","title":"晚秋归自京","author":"艾可叔","dynasty":"宋","verses":["红尘两脚几时休，此度真成浪漫游。","倦买夜船过钓濑，渴呼腊盏试龙游。","菊前疏雨重阳信，天际孤云万里愁。","昨夜江头乡国梦，已随明月度西楼。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.240000.json#record-8c37f701-22c5-482d-972e-1edce5ff0263","tags":[]},{"id":"poem-f7c0d9559b2338fa021d91e0","title":"颂古三十一首  其三","author":"释原妙","dynasty":"宋","verses":["死款都来一口供，情穷理极卒难容。","若将皮髓论高下，争见花开五叶红。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.240000.json#record-64bc7087-faf6-4881-84b5-ce1022f43efd","tags":[]},{"id":"poem-f7c1fac454cf92126b1a64ce","title":"减字浣溪沙・浣溪沙·鹦鹉无言理翠襟","author":"贺铸","dynasty":"宋","verses":["鹦鹉无言理翠襟。","杏花零落昼阴阴。","画桥流水半篙深。","芳径与谁寻斗草，绣床终日罢拈针。","小笺香管写春心。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.4000.json#record-120","tags":[]},{"id":"poem-f7ce8ce950ec78f4c5f90fc9","title":"鹧鸪天·说著分飞百种猜","author":"向子𬤇","dynasty":"宋","verses":["说著分飞百种猜。","泥人细数几时回。","风流可惯曾孤冷，怀抱如何得好开。","垂玉箸，下香阶。","凭肩小语更兜鞋。","再三莫遣归期误，第一频教入梦来。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.6000.json#record-752","tags":[]},{"id":"poem-f7d295ea0fe577771fe8252c","title":"后庭花·轻盈舞妓含芳艳","author":"毛熙震","dynasty":"五代","verses":["轻盈舞妓含芳艳，竞妆新脸。","步摇珠翠修蛾敛，腻鬟云染。","歌声慢发开檀点，绣衫斜掩。","时将纤手匀红脸，笑招金靥。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-x-juan.json#record-6","tags":[]},{"id":"poem-f7d4676d3ec59a27dbf3a31e","title":"秋","author":"李山甫","dynasty":"唐","verses":["傍雨衣风冷渐匀，更凭青女事精神。","来时将得几多雁，到处愁他无限人。","能被绿杨深懊恼，谩偎黄菊送殷勤。","邹家不用偏吹律，到底荣枯也自均。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.35000.json#record-d1ff3436-20ac-4495-8d40-e24c315e50f5","tags":[]},{"id":"poem-f7d6afdc33e5c15c61efac04","title":"南乡子·嫩草如烟","author":"欧阳炯","dynasty":"五代","verses":["嫩草如烟，石榴花发海南天。","日暮江亭春影绿，鸳鸯浴。","水远山长看不足。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-6-juan.json#record-0","tags":[]},{"id":"poem-f7db0726572d54951e3243af","title":"送崔校书赴梓幕","author":"司空曙","dynasty":"唐","verses":["碧峰天柱下，鼓角镇南军。","管记催飞檄，蓬莱辍校文。","栈霜朝似雪，江雾晚成云。","想出褒中望，巴庸方路分。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.15000.json#record-0659c894-8128-4d41-8136-e7afac1dcc33","tags":[]}];
